engine.answerStyles:
function answerStyles(mode) {
  var all = [
    { id: "keyphrase", rule: "Put the phrase that answers the question in <b>, so it stands out." },
    { id: "list", rule: "When a sentence names three or more items, set them out as <ul><li> bullets, in the same words." },
    { id: "label", tag: "h4", rule: "A group of bullets may get a short <h4> label of 2-6 words, e.g. <h4>The cap doesn't cover</h4>. Never put anything longer in <h4>." },
    { id: "quote", tag: "blockquote", rule: "Put a passage quoted from the document (a whole sentence or clause, set apart on its own) in <blockquote>, with its [N] marker inside it. A word or short phrase you mention inside your own sentence, such as a deleted “reasonable”, stays inline in quotation marks: never put <blockquote> in the middle of a sentence." },
    { id: "proposed", tag: "section", rule: "Put new contract wording you propose (a replacement clause, an insert, a redraft) in one <section>, and nothing else in it. Inside, give each heading its own <p><b>...</b></p> and each lettered or numbered item, such as (a), (b) or (i), its own <p> starting with that letter. Never use bullets inside <section>." },
    { id: "draft", tag: "article", rule: "When the user asks for an email, letter or memo, write the composition itself inside one <article>: for an email, start with <p><b>Subject:</b> ...</p>, then the greeting, short paragraphs and the sign-off. No headings, labels, tables or emoji inside it, whatever the other rules say. Anything you tell the user about it goes outside the <article>, after it." },
    { id: "layout", tailored: true, rule: "Beyond these rules, lay out THIS answer the way that makes it easiest to read: premium, calm and quick to scan. A short answer stays a short paragraph or two; structure is for answers that need it." },
    { id: "sections", tailored: true, tag: "h3", rule: "A longer answer with several distinct parts may give each part a short <h3> heading of 2-5 words, without numbers or emoji." },
    { id: "table", tailored: true, tag: "table", rule: "When comparing two or more things on the same points, use a <table> with a <th> header row, at most 3 columns and short cells." },
    { id: "calm", tailored: true, rule: "No emoji, no horizontal rules, no filler such as \"Great question!\" or \"Here's a breakdown\", and <b> only for the few phrases that matter." },
    { id: "free", free: true, tags: ["h3", "h4", "blockquote", "table", "hr"], rule: "Lay out THIS answer however you think reads best. Headings (<h3>, or <h4> for a smaller one), lists, tables, quote blocks (<blockquote>), dividing lines (<hr>) and emoji are all yours to use, or none of them." },
    { id: "expressive", expressive: true, tags: ["h3", "h4", "blockquote", "table", "hr", "section", "article"], rule: "You have free rein over the layout of THIS answer: headings (<h3>, or <h4> for a smaller one), tables, quote blocks (<blockquote>), dividing lines (<hr>) and emoji section markers are all yours to use as it suits. Keep it premium and professional, like a briefing from a leading law firm, never chatty: at most one emoji per heading, chosen for meaning (e.g. 🔑 key points, ⚠️ risks, ⚖️ trade-offs, ✍️ suggested wording, 🔴 🟠 🟡 for priority), ✅ before each recommended ask, and a longer answer may close with a 💡 Bottom line. Never put emoji mid-sentence, and use no filler or exclamation marks; bold only lead-ins and key figures. Quotes from the document go in <blockquote>; new contract wording you propose goes in a <section>; an email, letter or memo the user asks for goes in one <article> (an email starting with <p><b>Subject:</b> ...</p>), with no emoji inside it." },
  ];
  if (mode === "free" || mode === "expressive") return all.filter(function (s) { return s[mode]; });
  return all.filter(function (s) { return !s.free && !s.expressive && (mode === "tailored" || !s.tailored); });
}

// ─── [COMMENTS] Add as comments ──────────────────────────────────────
// The prompt for Word comments, for audience "team" | "other"; the three
// ways in are listed below, plus i.positions (commentPositions). Anchors are
// checked afterwards (parseComments) against the text each comment sits on.

engine.buildCommentsPrompt:
function buildCommentsPrompt(input) {
  var i = input || {};
  // Three ways in, one comment shape out:
  //   answer      { answerText, paragraphs }        — the issues an answer raised
  //   request     { instruction, docText, selectionText, userAuthors, redlineText, threads }
  //               — "add comments to all the revisions I made", "… requesting X",
  //               "respond to the other side's comments" (threads: the comments
  //               already in the document, which a reply goes onto)
  //   revisions   { revisions: [{ section, type, before, after, why }] }
  //               — the changes ELI Agent just made, one comment each
  var other = i.audience === "other";
  var mode = Array.isArray(i.revisions) ? "revisions" : i.instruction ? "request" : "answer";
  var paras = (Array.isArray(i.paragraphs) ? i.paragraphs : []).map(function (p) {
    return "    " + p.id + ": " + String(p.text || "").replace(/\s+/g, " ").slice(0, 1500);
  }).join("\n");
  var who = Array.isArray(i.userAuthors) && i.userAuthors.length
    ? " The user's own revisions are the ones by " + i.userAuthors.map(function (n) { return "\"" + n + "\""; }).join(" or ") + "."
    : "";
  var task = {
    answer: "Turn the issues raised in the ANSWER below into Word comments on the open contract.",
    request: "Follow the USER'S REQUEST below to write Word comments on the open contract.",
    revisions: "Write one Word comment for each REVISION below — the changes just made to the contract — explaining it.",
  }[mode];
  var scope = {
    answer: "- One comment per distinct issue the ANSWER raises; at most 8. Never add an issue the ANSWER does not raise.",
    request: "- Do exactly what the request asks: comment where it says, about what it says, and nothing else; at most 30. " +
      "If it is about revisions (tracked changes), comment on each matching one — the [INSERTED by …] / [DELETED by …] markers show who made each." + who +
      " \"This\" or \"here\" means the user's SELECTION, when there is one. If nothing matches, return an empty list.",
    revisions: "- Exactly one comment per REVISION, in the same order: what changed and why, using its reason.",
  }[mode];
  var pin = {
    answer: "- Pin each comment to the exact words it is about: 'paragraphId' is the id of one PARAGRAPH below, and 'anchor' is copied verbatim from that paragraph's text, 4 to 25 words.",
    request: "- Pin each comment to the exact words it is about: 'paragraphId' is the id of a paragraph in the DOCUMENT JSON, and 'anchor' is 4 to 25 words copied verbatim from that paragraph's CURRENT text — inserted text counts, deleted text does not; for a deletion, use the words right beside it. Never put [INSERTED by …]-style markers in an anchor.",
    revisions: "- 'paragraphId' is the revision's id (REV_1, REV_2, …) and 'anchor' is 4 to 25 words copied verbatim from that revision's NEW text (for a deletion, from the text deleted).",
  }[mode];
  // [COMMENT-POSITIONS] i.positions: commentPositions(…) for this audience;
  // null when "Use Colgate positions" is off.
  var pl = i.positions && Array.isArray(i.positions.items) ? i.positions : null;
  var has = !!(pl && pl.items.length);
  var forType = pl && pl.docType && pl.docType !== "Other" ? " for this " + pl.docType : "";
  var posRule = has
    ? (other
      ? "- Where a COLGATE POLICY item below applies, you may state it as Colgate policy, e.g. \"Colgate policy requires payment within 90 days\", and propose its wording. Say \"Colgate policy\" only for an item listed there."
      : "- Where a COLGATE POSITIONS item below applies, say what it requires, whether the draft meets it and which fallback fits; say when the draft breaks a locked clause or a mandatory rule, in ordinary lowercase. Never invent a position that is not listed.")
    : (other
      ? "- Never write \"Colgate policy\" or claim anything Colgate requires: " + (pl ? "none is on file" + forType : "none was provided") + "."
      : "- " + (pl ? "No Colgate positions are on file" + forType : "No Colgate positions were provided") + ": never state or invent one.");
  var posBlock = has
    ? ["", other ? "COLGATE POLICY — what Colgate requires" + forType + " (safe to tell the other side):"
        : "COLGATE POSITIONS — the team's own guidance and playbook" + forType + ":"]
        .concat(pl.items.map(function (p) { return "    " + p.ref + " · " + p.line; }))
    : [];
  // Replies: the comments already in the document, by id (CMT_1 …).
  var SIDE = { you: "you, the user", colleague: "Colgate colleague", counterparty: "other side" };
  var threads = mode === "request" && Array.isArray(i.threads) ? i.threads.filter(function (t) { return t && t.id; }) : [];
  var replyRule = threads.length
    ? "- To reply to an EXISTING COMMENT, set 'replyTo' to its id (CMT_1, …) and leave 'paragraphId' and 'anchor' empty. " +
      "\"Respond\" or \"reply\" to comments means replies: one to each comment the request covers (\"the other side's comments\" are those by the other side). " +
      "Answer what the comment says or asks. Never reply to the user's own comments, or to resolved ones, unless the request says so."
    : null;
  var tail = [];
  if (mode === "answer") {
    tail = ["ANSWER:", "\"\"\"", String(i.answerText || "").slice(0, 12000), "\"\"\"", "", "PARAGRAPHS (id: text):", paras || "    (none)"];
  } else if (mode === "request") {
    tail = ["USER'S REQUEST:", "\"\"\"", String(i.instruction || "").slice(0, 2000), "\"\"\""];
    if (i.selectionText && String(i.selectionText).trim().length > 4) {
      tail.push("", "SELECTION (what \"this\" means):", "\"\"\"", String(i.selectionText).slice(0, 4000), "\"\"\"");
    }
    tail.push("", "DOCUMENT (paragraph-indexed JSON — id, text, section):", String(i.docText || "").slice(0, 400000));
    if (i.redlineText) tail.push("", String(i.redlineText).slice(0, 200000));
    if (threads.length) {
      tail.push("", "EXISTING COMMENTS (id · author (side) · the words it is on · the comment · replies):");
      threads.slice(0, 80).forEach(function (t) {
        var one = function (x, n) { return String(x || "").replace(/\s+/g, " ").trim().slice(0, n); };
        tail.push("    " + t.id + " · " + one(t.author, 60) + " (" + (SIDE[t.side] || "side unknown") + ")" + (t.resolved ? " · RESOLVED" : "") +
          " · on \"" + one(t.on, 300) + "\" · \"" + one(t.content, 800) + "\"" +
          ((t.replies || []).length ? " · replies: " + t.replies.map(function (r) { return one(r.author, 60) + ": \"" + one(r.content, 300) + "\""; }).join(" / ") : ""));
      });
    }
  } else {
    tail = ["REVISIONS:"].concat(i.revisions.map(function (r, k) {
      return "    REV_" + (k + 1) + " · " + (r.section || "—") + " · " + (r.type || "replace") +
        "\n      before: " + String(r.before || "(nothing — new text)").replace(/\s+/g, " ").slice(0, 800) +
        "\n      after: " + String(r.after || "(deleted)").replace(/\s+/g, " ").slice(0, 800) +
        (r.why ? "\n      reason: " + String(r.why).replace(/\s+/g, " ").slice(0, 400) : "");
    }));
  }
  return [
    "You are ELI (Enhanced Legal Intelligence), working for in-house counsel at Colgate-Palmolive.",
    task,
    "",
    "AUDIENCE: " + (other
      ? "the OTHER SIDE (the counterparty). These comments will be sent to them."
      : "Colgate's OWN legal team. These are internal notes."),
    "",
    "RULES:",
    scope,
    pin,
    "- 'priority': \"must\" for essential points, \"worth\" for worth raising, \"minor\" for small ones.",
    "- 'issue': a 2-5 word label, e.g. \"Raw data ownership\".",
    "- 'text': the comment itself, 1-3 sentences of plain text — no markdown, no emoji, no mention of ELI or AI.",
    other
      ? "- For the other side: professional and constructive. Say what should change (or what was changed) and why: fairness" + (has ? ", market practice or Colgate policy" : " or market practice") + ". Never use the words \"playbook\", \"fallback\" or \"walk-away\"; never refer to Colgate's internal positions, team guidance, approvals or risk appetite; never suggest Colgate could accept less."
      : "- For Colgate's team: candid about the risk. Start every comment with \"Internal: \".",
    posRule,
    has && mode === "answer" ? "- The positions shape how each comment is worded; they never add an issue the ANSWER does not raise." : null,
    has && mode === "request" ? "- A request about Colgate's positions or policy (e.g. \"wherever the draft departs from them\") means: compare the DOCUMENT with each item listed below." : null,
    has ? "- 'source': the id (P1, P2, …) of the listed item the comment relies on, or \"\" for none." : null,
    replyRule,
    "",
    "Return RAW JSON only (no markdown, no preamble):",
    "{\"comments\":[{\"paragraphId\":\"" + (mode === "revisions" ? "REV_1" : "ELI_IDX_12") + "\",\"anchor\":\"…\",\"priority\":\"must\",\"issue\":\"…\"," + (has ? "\"source\":\"P1\"," : "") + "\"text\":\"…\"}]}",
  ].concat(posBlock, [""], tail).filter(function (l) { return l !== null; }).join("\n");
}

// Gemini's reply → the comments ELI can actually place: anchors checked
// against their paragraph (quotes, dashes and spacing forgiven); a comment
// whose anchor isn't there sits on the whole clause instead. For the other
// side, wording that gives away Colgate's thinking is flagged, and so is
// "Colgate policy" that no listed requirement backs; either starts unticked.
// positions: the commentPositions(…) the prompt listed (source P1 → its label).
// threads: the existing comments a reply may go onto ({ id, author, content }).

engine.parseComments:
function parseComments(raw, paragraphs, audience, max, positions, threads) {
  var obj = null;
  if (raw && typeof raw === "object") obj = raw;
  else {
    var s = String(raw || "").trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
    var a = s.indexOf("{"), b = s.lastIndexOf("}");
    try { obj = JSON.parse(a >= 0 && b > a ? s.slice(a, b + 1) : s); } catch (_e) { obj = null; }
  }
  var list = obj && Array.isArray(obj.comments) ? obj.comments : [];
  var norm = function (t) {
    return String(t || "").replace(/[‘’‚‛]/g, "'").replace(/[“”„‟]/g, "\"")
      .replace(/[‐-―]/g, "-").replace(/ /g, " ").replace(/\s+/g, " ").trim().toLowerCase();
  };
  var byId = {};
  (paragraphs || []).forEach(function (p) { if (p && p.id) byId[p.id] = norm(p.text); });
  // Phrases that give away Colgate's own thinking. Not plain contract words —
  // "internal business purposes" and "prior written approval" are fine.
  var LEAK = /\b(playbook|fallbacks?|our (?:internal )?position|colgate(?:'s)? (?:internal )?position|walk[- ]?away|our bottom[- ]line|risk appetite|internal(?:ly)? (?:position|view|guidance|note)|team guidance|we (?:can|could|would) (?:accept|live with|concede))\b/i;
  var POLICY = /\b(?:colgate(?:'s)?|our|company) polic(?:y|ies)\b/i;
  var refs = {}, byThread = {};
  ((positions && positions.items) || []).forEach(function (p) { if (p && p.ref) refs[String(p.ref).toUpperCase()] = p; });
  (threads || []).forEach(function (t) { if (t && t.id) byThread[String(t.id).toUpperCase()] = t; });
  var other = audience === "other";
  var out = [];
  list.slice(0, max > 0 ? max : 8).forEach(function (c, i) {
    if (!c || typeof c !== "object") return;
    var text = String(c.text || "").replace(/\s+/g, " ").trim();
    if (!text) return;
    // Internal notes always say so, whatever Gemini wrote.
    if (!other && !/^internal:/i.test(text)) text = "Internal: " + text;
    var pid = String(c.paragraphId || "").trim();
    var anchor = String(c.anchor || "").replace(/\s+/g, " ").trim();
    // Two words at least, so an anchor can't match by accident.
    var A = /\S\s+\S/.test(anchor) && anchor.length >= 8 ? norm(anchor) : "";
    var has = function (id) { return !!(A && byId.hasOwnProperty(id) && byId[id].indexOf(A) >= 0); };
    // The words decide the paragraph: a wrong id is corrected when the words
    // are in another pinned paragraph. A comment matching no pinned clause
    // is never put on some other one — it is marked and left unticked.
    if (!has(pid)) {
      var other_ = Object.keys(byId).filter(has)[0];
      if (other_) pid = other_;
    }
    if (!byId.hasOwnProperty(pid)) pid = "";
    var onWords = has(pid);
    var pr = String(c.priority || "").toLowerCase();
    var leak = other ? (text.match(LEAK) || [])[0] || "" : "";
    var src = refs[String(c.source || "").trim().toUpperCase()] || null;
    var policy = other && !src && POLICY.test(text) ? "No Colgate requirement on file says this." : "";
    var pr0 = String(c.priority || "").toLowerCase();
    // A reply goes onto an existing comment; one naming no comment there is kept, unticked.
    if (String(c.replyTo || "").trim()) {
      var th = byThread[String(c.replyTo).trim().toUpperCase()] || null;
      out.push({
        n: out.length + 1, reply: true,
        replyTo: th ? th.id : "", replyToAuthor: th ? String(th.author || "") : "",
        replyToText: th ? String(th.content || "").replace(/\s+/g, " ").trim().slice(0, 200) : "",
        paragraphId: "", anchor: "", noClause: !th,
        issue: String(c.issue || "").replace(/\s+/g, " ").trim().slice(0, 60) || ("Reply " + (i + 1)),
        priority: pr0 === "must" || pr0 === "minor" ? pr0 : "worth",
        text: text.slice(0, 1200), leak: leak, source: src ? src.label : "", policy: policy,
        keep: !!th && !leak && !policy,
      });
      return;
    }
    out.push({
      n: out.length + 1,
      paragraphId: pid,
      anchor: onWords ? anchor : "",
      noClause: !pid,
      issue: String(c.issue || "").replace(/\s+/g, " ").trim().slice(0, 60) || ("Issue " + (i + 1)),
      priority: pr === "must" || pr === "minor" ? pr : "worth",
      text: text.slice(0, 1200),
      leak: leak,
      source: src ? src.label : "",
      policy: policy,
      keep: !leak && !policy && !!pid,
    });
  });
  return out;
}

// [COMMENT-POSITIONS] Colgate's positions as the comments see them: P1, P2 …
// in the prompt, and a label for the review card (never put in Word). The
// team gets all of it. The other side gets only what Colgate requires — the
// preferred wording, and mandatory or strong rules — said as Colgate policy;
// fallbacks, reasons, lock notes and approval flags are never sent, so they
// can't leak. null in (positions off) → null out.

engine.commentPositions:
function commentPositions(positions, audience) {
  if (!positions) return null;
  var other = audience === "other";
  var one = function (t, n) { return String(t == null ? "" : t).replace(/\s+/g, " ").trim().slice(0, n); };
  var items = [];
  (positions.playbooks || []).forEach(function (c) {
    var name = one(c && c.clauseName, 80);
    if (!name) return;
    var pref = one(c.preferredLanguage, 600);
    if (other) {
      if (pref) items.push({ label: "Colgate policy — " + name, line: name + (c.locked ? " (required as written)" : "") + ": " + pref });
      return;
    }
    var parts = [];
    if (pref) parts.push("preferred language: " + pref);
    if (c.guidance) parts.push("why: " + one(c.guidance, 300));
    var fb = (c.fallbacks || []).filter(function (f) { return f && f.text; })
      .map(function (f) { return (f.level ? one(f.level, 40) + ": " : "") + one(f.text, 400); }).join(" / ");
    if (fb) parts.push("fallbacks: " + fb);
    if (c.lockNote) parts.push("lock note: " + one(c.lockNote, 300));
    items.push({ label: "Playbook — " + name + (c.locked ? " (locked)" : ""),
      line: "Playbook — " + name + (c.locked ? " [locked: must not change]" : "") + (c.approvalRequired ? " [changes need approval]" : "") +
        ": " + (parts.join(" | ") || "(no notes)") });
  });
  (positions.guidance || []).forEach(function (r) {
    var text = one(r && r.text, 400), tier = one(r && r.tier, 20) || "default", clause = one(r && r.clause, 80);
    if (!text) return;
    if (other) {
      if (tier === "mandatory" || tier === "strong") items.push({ label: "Colgate policy" + (clause ? " — " + clause : ""), line: (clause ? clause + ": " : "") + text });
      return;
    }
    items.push({ label: "Team guidance (" + tier + ")" + (clause ? " — " + clause : ""),
      line: "Team guidance (" + tier + ")" + (clause ? ", " + clause : "") + ": " + text });
  });
  items.forEach(function (p, k) { p.ref = "P" + (k + 1); });
  return { docType: one(positions.docType, 80), items: items };
}

// [COMMENTS] Does a message mention comments? A word within two typos of
// "comment(s)" — coment, commnet, commnets — that isn't one of the real
// words that close (content, moment, commit …).

engine.mentionsComments:
function mentionsComments(text) {
  var NOT = /^(?:contents?|connects?|cements?|moments?|commits?|comets?|commends?|common|commune|commas?)$/;
  function dist(a, b) {
    var prev = [], cur, i, j;
    for (j = 0; j <= b.length; j++) prev[j] = j;
    for (i = 1; i <= a.length; i++) {
      cur = [i];
      for (j = 1; j <= b.length; j++) {
        cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1));
      }
      prev = cur;
    }
    return prev[b.length];
  }
  return String(text || "").toLowerCase().split(/[^a-z]+/).some(function (w) {
    if (w.length < 5 || w.length > 10 || w.charAt(0) !== "c" || NOT.test(w)) return false;
    return dist(w, "comment") <= 2 || dist(w, "comments") <= 2;
  });
}

// The one question asked when a message mentions comments but the quick
// test didn't catch it: does it want comments added, or replies written?

engine.buildCommentCheckPrompt:
function buildCommentCheckPrompt(question) {
  return [
    "Does this message ask ELI to ADD comments to the Word document open in front of the user, or to REPLY to comments already in it?",
    "Asking ABOUT comments — what they say, who made them, whether to add some — is not that. A polite question (\"can you add a comment …?\") is a request. Read past typos (\"can youa dd a coment\").",
    "",
    "MESSAGE:",
    "\"\"\"",
    String(question || "").slice(0, 600),
    "\"\"\"",
    "",
    "Return JSON only: {\"comments\": true} or {\"comments\": false}",
  ].join("\n");
}

// ─── Prompt builders ─────────────────────────────────────────────────

// Build the standard QA prompt. Mirrors v2 PROMPTS.qaMain (data/prompts.js).
// Handles: history, current question, document text (with optional
// paragraph-indexed anchors), selection target, redline note + author
// roster, modify (rewrite/draft) mode, attached prefix.

engine.buildAskEliPrompt:
function buildAskEliPrompt(input) {
  var CAP = 20;
  var question = String(input.question || "").trim();
  var docText = String(input.docText || "");
  var selectionText = String(input.selectionText || "").trim();
  var attachmentPrefix = String(input.attachmentPrefix || "");
  var history = Array.isArray(input.history) ? input.history : [];
  var modifyMode = !!input.modifyMode;
  var hasRedlines = !!input.hasRedlines;
  var hasHighlights = !!input.hasHighlights;
  var comments = Array.isArray(input.comments) ? input.comments : [];
  var roster = input.roster || null;
  var useAnchors = !!input.useAnchors;
  var currentUserName = String(input.currentUserName || "Andrew");
  // [ANSWER-STYLES] The author names that are the user (from the Redline
  // Authors roster), so their edits are called "you" rather than by name.
  var currentUserAuthors = Array.isArray(input.currentUserAuthors) ? input.currentUserAuthors.filter(function (n) { return n && typeof n === "string"; }) : [];
  // [SETTINGS] Ask ELI settings dialog: answer length, follow-ups, and the
  // [POSITIONS] block (team guidance + playbook, off by default).
  var answerLength = input.answerLength === "short" || input.answerLength === "detailed" ? input.answerLength : "normal";
  var wantFollowups = input.followups !== false;
  var positions = input.positions || null;
  // [ANSWER-STYLES] Present only when "Formatted answers" is on; otherwise
  // formatBlock is empty and the prompt is exactly what it was.
  var formatStyles = Array.isArray(input.formatStyles) && input.formatStyles.length ? input.formatStyles : null;
  var formatBlock = "";
  if (formatStyles) {
    var fmtTags = [];
    formatStyles.forEach(function (s) {
      (s && s.tags ? s.tags : s && s.tag ? [s.tag] : []).forEach(function (g) { if (fmtTags.indexOf("<" + g + ">") < 0) fmtTags.push("<" + g + ">"); });
    });
    formatBlock =
      "    FORMATTING GUIDE for 'answer': layout only. Never shorten, drop, merge or reword anything to fit it; skip any rule that doesn't suit this answer; a format the user asks for (an email, a table, a memo) comes first." +
      (fmtTags.length ? " Besides <b>, <i>, <ul>, <ol>, <li>, <p> and <br>, you may use " + fmtTags.join(", ") + "." : "") + "\n" +
      formatStyles.filter(function (s) { return s && s.rule; }).map(function (s) { return "    - " + s.rule + "\n"; }).join("");
  }
  // 2026-05-16: attachment presence → force object citation shape so
  // ATT_<N> / ATT_P<N> ids round-trip. Otherwise attached-only path
  // (useAnchors=false) would emit plain-string citations with no id,
  // so attached citations couldn't be styled distinctly or routed to
  // the doc viewer. Detected by sniffing for the marker
  // buildAttachmentPrefix emits.
  var hasAttachment = /=== ATTACHED (FILE|PDF)/.test(attachmentPrefix);
  var needObjectCitations = useAnchors || hasAttachment;

  // History block — last 10 turns max. Plain text, no JSON/HTML.
  var historyBlock = "";
  if (history.length) {
    historyBlock = history.slice(-CAP).map(function (turn) {
      var role = turn.role === "model" ? "ELI" : "User";
      return role + ": " + String(turn.content || "");
    }).join("\n");
  }

  // Selection-aware mode block. FROM v2 qaModeTargetSelection.
  var modeBlock = "";
  if (selectionText && selectionText.length > 4) {
    modeBlock =
      "\n    CONTEXTUAL ANALYSIS RULE:\n" +
      "    - The user has highlighted a specific section (TARGET SELECTION).\n" +
      "    - Focus your answer on that selection.\n" +
      "    - HOWEVER, you MUST cross-reference the FULL DOCUMENT CONTEXT to check for definitions, conflicting clauses, or overriding terms that affect the selection.\n";
  }

  // Always-broad mode — falls back to general legal knowledge when the
  // doc doesn't contain the answer. FROM v2 qaModeBroad.
  var broadBlock =
    "\n    MODE: BROAD / CONSULTANT\n" +
    "    - Base your facts on the document.\n" +
    "    - If the user asks for opinions, explanations, or 'market standards' that are not in the file, USE YOUR GENERAL KNOWLEDGE to answer helpfully.\n" +
    "    - FORMATTING: Use HTML tags for structure (<b>bold</b>, <ul><li>lists</li></ul>, <br> breaks).\n";

  // Author roster block — only when redlines present + roster provided.
  // FROM v2 qaAuthorRoster + qaRedlineNote.
  var rosterBlock = "";
  if (hasRedlines && roster && typeof roster === "object") {
    var internal = [], external = [], unknown = [];
    Object.keys(roster).forEach(function (name) {
      var side = String(roster[name] || "").toLowerCase();
      if (side === "internal") internal.push(name);
      else if (side === "external") external.push(name);
      else unknown.push(name);
    });
    var firstUnknown = unknown[0] || "";
    rosterBlock =
      "\n\n    CONFIRMED AUTHOR ROSTER (USER-VERIFIED GROUND TRUTH — TRUST THIS OVER ANY HEURISTIC):\n" +
      "    - INTERNAL / Colgate side: " + (internal.join(", ") || "(none)") + "\n" +
      "    - EXTERNAL / Counterparty side: " + (external.join(", ") || "(none)") + "\n" +
      "    - UNKNOWN side: " + (unknown.join(", ") || "(none)") + "\n" +
      "    Use these classifications verbatim. For UNKNOWN authors, refer by name without claiming a side. " +
      (firstUnknown ? "(e.g. \"" + firstUnknown + " inserted...\")" : "") + "\n";
  }
  var redlineNote = hasRedlines
    ? ("\n    REDLINE NOTE: This document contains tracked changes. Edits are marked inline as " +
       "[INSERTED by Author on YYYY-MM-DD: text], [DELETED by Author on YYYY-MM-DD: text], " +
       "[MOVED FROM by Author on YYYY-MM-DD: text], or [MOVED TO by Author on YYYY-MM-DD: text]. " +
       "Dates are present when Word recorded them; some older edits may show only \"by Author\" with no date. " +
       "The current Colgate user is \"" + currentUserName + "\". " +
       (currentUserAuthors.length
         ? "Their own tracked changes and comments are recorded under " + currentUserAuthors.map(function (n) { return "\"" + n + "\""; }).join(" and ") +
           ": always call those \"you\"/\"your\", never by name. "
         : "") +
       "Use \"you\"/\"your\" ONLY for edits whose author matches the current user. For other internal " +
       "edits, name the colleague (e.g. \"Your colleague X inserted...\"). For external edits, identify " +
       "the counterparty by name. Do NOT include bracket markers in your answer text — describe naturally. " +
       "When the user asks WHEN something changed, use the dates from these markers." +
       rosterBlock + "\n")
    : "";
  // Highlight note — always added when any highlighted text exists in the
  // doc, with or without redlines. [HIGHLIGHTED color: text] markers come
  // from markRedlinesInOoxml's per-paragraph highlight pass.
  var highlightsNote = hasHighlights
    ? ("\n    HIGHLIGHTS NOTE: Some text in the document is wrapped with [HIGHLIGHTED color: text] markers — " +
       "these are visual highlights the user added with Word's highlight tool (yellow is the default, but any color works). " +
       "Highlights typically signal \"revisit this\", \"open question\", or \"attention needed\". " +
       "When the user asks \"what did I highlight\" / \"what's in yellow\" / \"any open items\" / \"what needs revisiting\", " +
       "surface the highlighted text. Do NOT include bracket markers in your answer text — describe naturally.\n")
    : "";
  // Comments block — margin annotations + replies + resolved state.
  // Comments live in a separate OOXML part (word/comments.xml), so they
  // don't appear inline in the doc text. We surface them as a top-level
  // block here. The AI relates them by content (mention of "Section 5",
  // "this clause", etc.) rather than precise position — sufficient for
  // negotiation-memory questions without requiring range-mapping.
  var commentsBlock = "";
  var commentsNote = "";
  if (comments.length) {
    var capped = comments.slice(0, 100);
    var truncated = comments.length > 100;
    var lines = capped.map(function (c, i) {
      var dateBit = c.date ? " (" + c.date + ")" : "";
      var resolvedBit = c.resolved ? " [RESOLVED]" : "";
      var content = String(c.content || "").replace(/\s+/g, " ").trim().slice(0, 800);
      var head = "    " + (i + 1) + ". " + (c.author || "Unknown") + dateBit + resolvedBit + ": \"" + content + "\"";
      var replyLines = (c.replies || []).slice(0, 10).map(function (r) {
        var rd = r.date ? " (" + r.date + ")" : "";
        var rc = String(r.content || "").replace(/\s+/g, " ").trim().slice(0, 500);
        return "         ↳ Reply from " + (r.author || "Unknown") + rd + ": \"" + rc + "\"";
      });
      return [head].concat(replyLines).join("\n");
    });
    var tail = truncated ? ("\n    ...and " + (comments.length - 100) + " more comments not shown.") : "";
    commentsBlock = "\n    DOCUMENT COMMENTS (margin annotations / negotiation notes — " + comments.length + " total):\n" + lines.join("\n") + tail + "\n";
    commentsNote =
      "\n    COMMENTS USAGE: The DOCUMENT COMMENTS block above lists margin annotations on the doc — " +
      "outstanding questions, flags for revisit, back-channel discussion between reviewers. " +
      "When the user asks \"what's been commented\" / \"any open issues\" / \"what did counterparty flag\" / " +
      "\"what did Andrew note\", surface these. Comments tagged [RESOLVED] are settled; treat unresolved as live. " +
      "The internal/external author classification from the redline roster (if present) also applies to comment authors. " +
      "Cite comments by author + date when referring to them in your answer.\n";
  }

  // Modify-mode task instruction. FROM v2 qaTaskModification.
  var taskBlock;
  // CITATION FORMAT — when useAnchors is true, citations are returned as
  // OBJECTS with id (matching the JSON paragraph-array's id) so the
  // frontend can jump precisely. Falls back to plain strings when
  // anchors aren't available (e.g. attached-only path).
  var citeShape = needObjectCitations
    ? "{ \"id\": \"ELI_IDX_<N>\" | \"ATT_<N>\" | \"ATT_P<page>\", \"text\": \"verbatim or near-verbatim excerpt for [1]\" }"
    : "\"verbatim excerpt for [1]\"";
  var citeIdRule = needObjectCitations
    ? "    - Each citation's 'id' MUST be the EXACT id from the source it came from: 'ELI_IDX_<N>' (live document JSON above), 'ATT_<N>' (attached file JSON above), or 'ATT_P<page>' (attached PDF, page number). The id is what makes the [N] pin clickable — without it the pin can't jump to the source. Citations from the attached file/PDF MUST use the ATT_ prefix so the frontend opens the document viewer instead of jumping in the live doc.\n"
    : "";

  if (modifyMode) {
    taskBlock =
      "TASK: You may MODIFY the document. If the user is asking to change/rewrite/strengthen/draft a specific clause, return RAW JSON:\n" +
      "    {\n" +
      "      \"action\": \"replace_text\",\n" +
      "      \"target_original\": \"EXACT_VERBATIM_STRING_FROM_DOCUMENT_TO_REPLACE\",\n" +
      "      \"proposed_new\": \"YOUR_STRONGER_OR_NEW_TEXT\",\n" +
      "      \"explanation\": \"Short summary of what changed and why.\"\n" +
      "    }\n" +
      "    HEADER RULE: INCLUDE manually-typed section headers (e.g. \"5.3 Liability:\", \"Indemnification.\") in target_original AND in proposed_new — the surgical rebuilder preserves their formatting per-word and the diff treats unchanged tokens as equals. EXCLUDE auto-generated list numbering that Word's auto-numbered list inserts dynamically (those don't appear in the searchable text). When in doubt, include the header — apply will still work because the rebuilder anchors on the surrounding words.\n" +
      "    PARAGRAPH RULE: If the selected/target text spans MULTIPLE paragraphs, preserve that structure — separate paragraphs with a newline (\\n) in BOTH target_original and proposed_new, and return the SAME number of paragraphs in proposed_new as in target_original (one rewritten paragraph per original paragraph). Never merge several paragraphs into one.\n" +
      "    If the user is NOT asking to modify a specific string, fall back to the standard answer shape:\n" +
      "    { \"answer\": \"<HTML answer with [N] markers>\", \"citations\": [" + citeShape + ", ...], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"], \"applyAction\": null }\n" +
      formatBlock +
      citeIdRule;
  } else {
    // Standard answer task. FROM v2 qaTaskStandard.
    taskBlock =
      "TASK: Return RAW JSON (no markdown, no preamble):\n" +
      "    { \"answer\": \"<HTML answer with [N] markers inline next to claims>\", \"citations\": [" + citeShape + ", " + citeShape + "], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"], \"applyAction\": \"Make these changes\" }\n" +
      "    FORMAT RULE: If the user explicitly asks for a specific OUTPUT FORMAT — e.g. an email, a letter, a memo, a bulleted list, or a table — produce 'answer' in that exact format as HTML (an email with a Subject line, greeting, body, and sign-off; a table as <table>…; etc.). Ground the content in the document, but for this composed/generated prose CITATIONS ARE OPTIONAL: add a [N] pin only where you directly quote or paraphrase a specific clause, and never force pins onto greetings, closings, headings, or wording you generated. The 'cite generously' rule below applies to normal question-answering, NOT to a requested composition. When no specific format is requested, answer normally per the rules below.\n" +
      "    ⚠️ HTML, NEVER MARKDOWN: 'answer' is rendered as HTML straight onto the page. Markdown is not converted — asterisks, hashes and backticks are printed to the user exactly as you type them, which looks broken. Use <b> for bold, <i> for italic, <ul><li> for bullets, <ol><li> for numbered lists, <p> for paragraphs, <br> for a line break. NEVER use **, *, ***, #, ##, ` or ``` for ANY purpose. A bare newline is NOT a paragraph break — an answer with no tags renders as one run-on block.\n" +
      formatBlock +
      "    INLINE CITATION RULE:\n" +
      "    - Every entry in 'citations' MUST have a matching [N] marker placed INLINE in 'answer', adjacent to the claim it supports.\n" +
      "    - Number of [N] markers MUST equal length of citations array.\n" +
      "    - The reverse also holds: NEVER write a [N] marker without a matching entry in 'citations'. A marker with nothing behind it is a footnote number pointing at nothing, and it is stripped — so the claim loses the support you meant to give it. If you have no quote to cite, write the sentence with no marker.\n" +
      "    - Cite generously: every factual claim that came from the document deserves a citation. Prefer verbatim text but a near-verbatim excerpt of the sentence the AI is referencing is also acceptable. The pin lets the user jump to the source — silent omission is worse than an approximate citation.\n" +
      "    ⚠️ CITATION CONTENT RULE: Each citation's 'text' MUST be verbatim or near-verbatim content COPIED FROM the cited source. Citations are quotes the user can click to locate in the document — they are NOT a slot for commentary. NEVER use the citations array to express absence, missing content, or what the source does NOT contain. If the source doesn't support a claim, write that observation in 'answer' WITHOUT a citation marker, and omit the citation entirely. Examples of FORBIDDEN citation text: 'The document does not contain X', 'There is no Section X in this file', 'Not found in the attached PDF', 'I could not locate X'. These belong in 'answer', not in citations.\n" +
      "    ⚠️ CRITICAL — INLINE MARKER vs PARAGRAPH ID: The [N] inline marker in 'answer' is the 1-based INDEX into the citations array — [1] for the first citation, [2] for the second, [3] for the third, etc. It is NOT the paragraph id from the JSON, NOT the page number, NOT the ATT_ token. Using anything other than a 1-based array index will break the pin.\n" +
      "    WRONG (numeric id leak):  \"...IP is fragmented [64]...\" because the cited paragraph is ELI_IDX_64.\n" +
      "    WRONG (ATT_ id leak):     \"...the term is 5 years [ATT_PDF]...\" or \"...as defined [ATT_3]...\" — these are CITATION IDS, not inline markers.\n" +
      "    RIGHT:                    \"...the term is 5 years [1]...\" with citations[0].id = 'ATT_PDF' (or 'ATT_P3' or 'ATT_3').\n" +
      "    Always use [1], [2], [3] inline. The id (ATT_PDF, ELI_IDX_64, etc.) belongs ONLY inside the citation object's 'id' field.\n" +
      citeIdRule +
      (wantFollowups
        ? "    'followups' must contain EXACTLY 2 concise actionable commands (4-8 words each) written from the user's perspective (e.g. \"Draft a mutual version\", \"Explain the key risks\"), NOT questions from you.\n"
        : "    'followups' must be an empty array [] — the user has turned follow-up suggestions off.\n") +
      (answerLength === "short"
        ? "    LENGTH: the user wants SHORT answers — lead with the direct answer in 1-3 sentences (or up to 4 bullets); skip background they did not ask for. Citations still apply.\n"
        : answerLength === "detailed"
          ? "    LENGTH: the user wants DETAILED answers — cover every relevant clause, exception, carve-out and cross-reference, using headings or bullets where it helps.\n"
          : "") +
      // When the answer recommends changing the document, the next thing
      // the reader wants is for it to BE changed — and retyping the advice
      // as an instruction is the friction that stops that happening.
      "    'applyAction': the label for a button that hands your recommendations to the revision agent, which then makes them.\n" +
      "    SET IT whenever your answer recommends changing the open document — that includes every answer to \"how would you improve this\", \"what would you change\", \"what's missing\", \"is this one-sided\", \"review this for me\", and any answer that suggests adding, removing, tightening or rewording anything. If a reader could act on your answer by editing the document, set it.\n" +
      "    Word it as the button it is: \"Make this change\" for one, \"Make these changes\" for several.\n" +
      "    Set it to null ONLY when there is nothing to act on: the answer purely explains or locates something, or you explicitly recommend no change, or the change would be to a document that is not open.\n";
  }

  // Selection block — verbatim text the user highlighted, capped at 4000
  // chars to keep prompt size sane.
  var selectionBlock = (selectionText && selectionText.length > 4)
    ? ("\n    TARGET SELECTION (USER HIGHLIGHTED):\n    \"\"\"\n    " + selectionText.substring(0, 4000) + "\n    \"\"\"\n")
    : "";

  // Document text — trimmed to 200K chars. When useAnchors is true, the
  // docText already has ELI_IDX_<id> anchors embedded by getQaAnchorPayload.
  var docHeader = useAnchors
    ? "    LIVE WORD DOCUMENT (FULL CONTEXT, paragraph-indexed JSON — each entry: id, text, and section):\n"
    : "    LIVE WORD DOCUMENT (FULL CONTEXT):\n";
  var docBlock = docText
    ? (docHeader + "    " + docText.substring(0, 500000) + "\n")
    : "    (No document text available.)\n";

  // Section context rule — the paragraph-indexed payload's entries carry
  // a 'section' field from the kernel structural map (the same section
  // mapping error_review uses). Tells the model to anchor answers to the
  // document's real structure rather than treating it as a flat blob.
  var sectionRule = useAnchors
    ? "\n    SECTION CONTEXT: Each paragraph object may carry a 'section' field — the document section/article it sits in (e.g. \"Article V › §5.3 Indemnification\"). When present, use it to:\n" +
      "    - Anchor every answer to the document's real structure: name the section a clause lives in (\"§5.3 Indemnification caps liability at...\"), don't just quote loose text.\n" +
      "    - Reason ACROSS sections: a defined term, cap, carve-out, or cross-reference in one section that affects another.\n" +
      "    - Tell the user WHERE in the agreement something is, by section number, so they can navigate there.\n"
    : "";

  // [POSITIONS] The team's own guidance + playbook for this agreement type
  // (loaded by eli_agent, off by default). Not document text — never pinned.
  var positionsBlock = "";
  if (positions) {
    var forType = positions.docType && positions.docType !== "Other" ? "a " + positions.docType : "this type of agreement";
    var posLines = [];
    (positions.guidance || []).forEach(function (r) {
      posLines.push("    - Team guidance (" + (r.tier || "default") + ")" + (r.clause ? ", " + r.clause : "") + ": " + r.text);
    });
    (positions.playbooks || []).forEach(function (c) {
      var fb = (c.fallbacks || []).map(function (f) { return (f.level ? f.level + ": " : "") + f.text; }).join(" / ");
      var parts = [];
      if (c.preferredLanguage) parts.push("preferred language: " + c.preferredLanguage);
      if (c.guidance) parts.push("Why: " + c.guidance);
      if (fb) parts.push("Fallbacks: " + fb);
      if (c.lockNote) parts.push("Lock note: " + c.lockNote);
      posLines.push("    - Playbook — " + c.clauseName +
        (c.locked ? " [LOCKED: this language must not change]" : "") +
        (c.approvalRequired ? " [changes need approval]" : "") +
        ": " + parts.join(" | "));
    });
    positionsBlock = posLines.length
      ? "\n    COLGATE POSITIONS — this team's own guidance and playbook for " + forType + ":\n" + posLines.join("\n") + "\n" +
        "    POSITIONS RULE: when the question touches a topic one of these covers, compare what the document says with Colgate's position. For each position that applies (at most three), add its own short paragraph to 'answer': <p><b>Colgate position:</b> what Colgate requires, in plain words; then whether the draft meets it; then its source in brackets: (Playbook: <clause name>), (Team guidance, mandatory) or (Team guidance).</p> Never fold two positions into one line. Always say when the draft breaks a mandatory rule or a locked clause, writing \"locked\" and \"mandatory\" in ordinary lowercase (e.g. \"so it breaks this locked position\"), never in capitals, and never using the labels from the list above (such as \"Playbook clause\"). Never invent a position that is not listed here, and say nothing about positions when none is relevant. These are not document text: never give them [N] markers or put them in 'citations'.\n"
      : "\n    COLGATE POSITIONS: none on file for " + forType + ". If the user asks for Colgate's position, say there is nothing on file for this agreement type — never supply one from general knowledge.\n";
  }

  // Final assembly. attachmentPrefix is prepended (e.g. for "both" scope
  // or attached-only). It's already shaped with `=== ATTACHED FILE ===`
  // headers by buildAttachmentPrefix.
  return [
    "You are 'ELI', an AI legal assistant for Colgate-Palmolive's legal team.",
    "    PERSPECTIVE: The user asking is ALWAYS a Colgate lawyer reviewing this agreement from Colgate's side.",
    "    When the user says 'we', 'us', or 'our', they mean Colgate. Treat the other party as the counterparty.",
    historyBlock ? "    CONVERSATION SO FAR:\n" + historyBlock : "",
    "    CURRENT QUESTION: " + question,
    selectionBlock,
    attachmentPrefix ? "    " + attachmentPrefix : "",
    docBlock,
    sectionRule,
    positionsBlock,
    commentsBlock,
    modeBlock + broadBlock + redlineNote + highlightsNote + commentsNote,
    taskBlock,
  ].filter(Boolean).join("\n");
}

// FROM v2 _isTranslateRequest. Cheap regex; init checks before sending
// to AI and routes through a separate prompt path.

engine.isTranslateRequest:
function isTranslateRequest(question) {
  if (!question) return false;
  var s = String(question);
  return /\btranslate(d|s|ing)?\b/i.test(s) || /\btranslation\b/i.test(s);
}

// Translate prompt builder. Two variants: HTML (when selection contains
// tables) preserves table markup; text strips to plain. FROM v2 lines
// 11260-11328.

engine.buildTranslatePrompt:
function buildTranslatePrompt(input) {
  var question = String(input.question || "").trim();
  var sourceText = String(input.sourceText || "").trim();
  var sourceHtml = String(input.sourceHtml || "").trim();
  var hasTables = /<table[\s>]/i.test(sourceHtml);
  if (hasTables) {
    return [
      "You are a legal translator.",
      "TASK: " + question,
      "Preserve all HTML table markup (<table>, <tr>, <td>, <th>) — translate ONLY the text content inside.",
      "Return RAW JSON: { \"hasTables\": true, \"html\": \"<the translated HTML>\" }",
      "",
      "SOURCE HTML:",
      sourceHtml.substring(0, 100000),
    ].join("\n");
  }
  return [
    "You are a legal translator.",
    "TASK: " + question,
    "Return RAW JSON: { \"hasTables\": false, \"text\": \"<the translated plain text>\" }",
    "",
    "SOURCE TEXT:",
    sourceText.substring(0, 100000),
  ].join("\n");
}

// Build the attachment prefix for the standard prompt. FROM v2
// _buildAttachmentPrefix (line 11352). Concatenates active template payload,
// attached-text file payload, and PDF marker (the actual PDF bytes flow as
// inlineData in the AI call, not in the text prefix).
//
// 2026-05-16: attached text is now paragraph-indexed as JSON ([{id:"ATT_1",
// text:"..."}, ...]) so the AI can cite by paragraph id and the viewer
// can scroll to the cited paragraph. PDFs get an ATT_P<page> citation
// rule. Citations whose id starts with "ATT_" route to the doc viewer
// (different chip color); citations with no ATT_ prefix route to the
// live Word doc as before.

engine.buildAttachmentPrefix:
function buildAttachmentPrefix(input) {
  var pre = "";
  if (input.activeTemplatePayload) pre += String(input.activeTemplatePayload) + "\n";
  if (input.attachedText) {
    var name = input.attachedName || "document";
    var rawText = String(input.attachedText).substring(0, 500000);
    // 2026-05-16: prefer HTML-block-derived paragraphs (init.js extracts
    // these from mammoth output) so the AI's ATT_<N> index matches the
    // viewer's block enumeration exactly. Fallback splits raw text on
    // blank lines for sources where HTML extraction isn't available
    // (e.g., plain TXT or DOCX where mammoth failed).
    var paras;
    if (Array.isArray(input.attachedParagraphs) && input.attachedParagraphs.length) {
      paras = input.attachedParagraphs.slice(0, 2000).map(function (p) {
        return String(p || "").replace(/\s+/g, " ").trim();
      }).filter(function (p) { return p.length > 0; });
    } else {
      paras = rawText.split(/\n\s*\n/).map(function (p) {
        return p.replace(/\s+/g, " ").trim();
      }).filter(function (p) { return p.length > 0; }).slice(0, 2000);
    }
    if (paras.length === 0) paras = [rawText.replace(/\s+/g, " ").trim()];
    var indexed = paras.map(function (text, i) {
      return { id: "ATT_" + (i + 1), text: text };
    });
    pre += '=== ATTACHED FILE (' + name + ', paragraph-indexed JSON) ===\n' +
           JSON.stringify(indexed) + '\n' +
           'CITATION RULE FOR ATTACHED FILE: when citing from this attached file, ' +
           'each citation object\'s "id" MUST be the EXACT id from this JSON ' +
           '(e.g. "ATT_5"). The "ATT_" prefix tells the frontend to open the ' +
           'document viewer at that paragraph.\n';
  }
  if (input.attachedPdfMarker) {
    var pdfName = input.attachedName || "document";
    pre += '=== ATTACHED PDF (' + pdfName + ') ===\n' +
           '(Content provided as inline PDF data below)\n' +
           'CITATION RULE FOR ATTACHED PDF: when citing from this PDF, use ' +
           '"id": "ATT_P<page>" where <page> is the page number you saw the ' +
           'text on (e.g. "ATT_P3"). If you cannot determine the page, use ' +
           '"id": "ATT_PDF". The "ATT_" prefix tells the frontend to open ' +
           'the PDF viewer at that page.\n';
  }
  return pre;
}

// ─── AI response parsing ─────────────────────────────────────────────

// Robust JSON-extract from Gemini response. FROM v2 tryParseGeminiJSON.
// AI sometimes wraps JSON in ```json fences or adds preamble; strip and
// try to parse. Return parsed object OR `{answer: "<raw text>"}` fallback.

engine.parseAiResponse:
function parseAiResponse(raw) {
  if (raw == null) return { answer: "" };
  var s = String(raw).trim();
  // Strip ```json … ``` fences.
  s = s.replace(/^```(?:json|html)?\s*/i, "").replace(/```\s*$/, "").trim();
  // Try direct parse.
  try {
    var direct = JSON.parse(s);
    if (direct && typeof direct === "object") return direct;
  } catch (e) { /* fall through */ }
  // Find first { and last } — Gemini often wraps JSON in chatter.
  var first = s.indexOf("{"), last = s.lastIndexOf("}");
  if (first !== -1 && last > first) {
    try {
      var sliced = JSON.parse(s.slice(first, last + 1));
      if (sliced && typeof sliced === "object") return sliced;
    } catch (e) { /* fall through */ }
  }
  // Tolerant retry — models often emit RAW newlines/tabs INSIDE string values
  // (e.g. a multi-paragraph proposed_new), which JSON.parse rejects. Escape
