      (lead || "") +
      '<span class="' + cls + '" data-cite-n="' + (idx + 1) + '" data-cite-id="' + cId + '" ' +
      'data-cite-text="' + cleanText + '" title="' + title + '">' + icon + '</span>' +
      '</span>' +
      (punct || "") + (trail || "");
  });
  return { html: chipped, count: matched, total: citations.length };
}

// [SECTION-PINS] A section the answer names — "§5.3", "Section 12.4(b)", "Sections 4.1 and 4.2", "clause 7" — gets a
// pin to that section's first paragraph in the document's index, unless a pin already follows it: the model is asked
// to cite every claim and often doesn't (the owner, 10-20: "a lot of answers without section cites"). A section is
// found by its 'section' label (Word's numbering) or, where the numbers are typed, by a paragraph opening with the
// number ("12.4 Governing Laws."). A number the document has no section for (a statute's) gets none. The pins go in as
// id markers ("[ELI_IDX_42]", which renderCitations maps by id), so the model's own markers keep their meaning: its
// groups ("[2, 3]") spelled out and any [N] beyond its citations stripped, or kept by its id's number — exactly as
// renderCitations would have read them. index: the paragraph-indexed payload ([{ id, text, section? }]).
// Returns { answer, citations, added }.

