  html = html.replace(/\[\s*([A-Z0-9_]+(?:\s*[-–—]\s*\d+)?(?:\s*(?:,|;|and|&amp;|&)\s*[A-Z0-9_]+(?:\s*[-–—]\s*\d+)?)*)\s*\]/g, function (full, inner) {
    if (!/,|;|\band\b|&|\d\s*[-–—]\s*\d/.test(inner)) return "[" + inner + "]";   // [CITE-GROUPS] as renderCitations
    var out = [];
    inner.split(/\s*(?:,|;|\band\b|&amp;|&)\s*/).forEach(function (piece) {
      var r = piece.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
