    if (!p.added && !p.removed) {
      if (currentHunk) { hunks.push(currentHunk); currentHunk = null; }
      p.value.forEach(function (w) { hunks.push({ type: "equal", text: w }); });
    } else {
      if (!currentHunk) currentHunk = { type: "change", oldWords: [], newWords: [], id: "hunk_" + hunks.length };
      if (p.removed) p.value.forEach(function (w) { currentHunk.oldWords.push(w); });
      if (p.added)   p.value.forEach(function (w) { currentHunk.newWords.push(w); });
    }
  });
  if (currentHunk) hunks.push(currentHunk);
  return hunks;
}

// ─── [REDLINE-ORDER] Tracked changes in the document's own order ─────
// The text as Word shows it, from its own tracked changes: kept words,
// deletions and insertions where they sit (a diff of before and after
// would always put a deletion first). changes: Word's tracked changes in
// document order, [{ type, text }]. Returns [{ t: "txt"|"del"|"ins", s, i }]
// (i = the change's index), or null when they don't line up with the texts
// (a change running past the range, say).

engine.orderRedlines:
function orderRedlines(orig, cur, changes) {
  orig = String(orig || ""); cur = String(cur || "");
  var ch = [];
  (changes || []).forEach(function (c, i) {
    var t = String((c && c.text) || ""), ty = String((c && c.type) || "");
    if (t && /delet|add|insert/i.test(ty)) ch.push({ del: /delet/i.test(ty), t: t, i: i });
  });
  if (!ch.length) return null;
  var segs = [], budget = 4000;
  function walk(k, o, c) {
    if (--budget < 0) return false;
    if (k === ch.length) {
      if (orig.slice(o) !== cur.slice(c)) return false;
      if (o < orig.length) segs.push({ t: "txt", s: orig.slice(o) });
      return true;
    }
    var x = ch[k], src = x.del ? orig : cur, from = x.del ? o : c;
    // Each change at a spot where the kept text before it reads the same in both.
    for (var at = src.indexOf(x.t, from); at >= 0; at = src.indexOf(x.t, at + 1)) {
      var kept = src.slice(from, at);
      if (kept !== (x.del ? cur.slice(c, c + kept.length) : orig.slice(o, o + kept.length))) return false;
      var n = segs.length;
      if (kept) segs.push({ t: "txt", s: kept });
      segs.push({ t: x.del ? "del" : "ins", s: x.t, i: x.i });
      if (x.del ? walk(k + 1, at + x.t.length, c + kept.length) : walk(k + 1, o + kept.length, at + x.t.length)) return true;
      segs.length = n;
    }
    return false;
  }
  return walk(0, 0, 0) ? segs : null;
}

// ─── Markdown-lite ───────────────────────────────────────────────────

// FROM v2 addChatBubble plain-text branch. Converts an answer to HTML when
// the caller passes raw text rather than HTML. Used for AI answers, user
// bubbles and activity-feed restoration.
//
// It used to handle bold, italic and newlines ONLY, which left every other
// piece of structure on screen as literal characters — "### Standard
// Position", "> quoted clause", "1." — and that is the answer that "isn't
// formatted". Worse, the italic rule ran over the whole string at once, so
// the "*" opening one bullet paired with the "*" opening the NEXT one and
// swallowed the line between them:
//     * No cap unless negotiated        ->  <i> No cap unless negotiated
//     * Consequential damages excluded       </i> Consequential damages…
// Hence "sometimes fine, other times all together": it depended entirely on
// whether the model happened to answer in prose.
//
// Now: blocks first (heading / quote / list / paragraph), inline formatting
// applied PER LINE so a marker can never pair across lines, and escaping
// still done before any markup is added.
// The answer is asked for as HTML. When the model sends markdown anyway,
// the markers land on screen as a literal "**Governing law**" — which is
// the one thing a finished answer must never look like.
//
// So: convert what can be converted, and DELETE what cannot. An unclosed
// marker is not content; it is the residue of a format nobody asked for.
//
// Markup-AWARE, not an escaper. The string is split on tags and only the
// text between them is touched, so existing HTML passes through intact and
// a "*" inside a title attribute or a data-cite-text value is left alone.
// Underscores are deliberately untouched: they are markdown emphasis in
// theory and snake_case in practice, and mangling a quoted defined term is
// worse than an italic that did not render.

engine.stripMarkup:
function stripMarkup(html) {
  var s = String(html == null ? "" : html);
  return s.split(/(<[^>]*>)/).map(function (part, i) {
    if (i % 2) return part;                       // a tag — never touched
    var t = part;
    t = t.replace(/`([^`\n]{1,200})`/g, "<code>$1</code>");
    t = t.replace(/\*\*\*([^*\n]+)\*\*\*/g, "<b><i>$1</i></b>");
    t = t.replace(/\*\*([^*\n]+)\*\*/g, "<b>$1</b>");
    t = t.replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,;:!?]|$)/g, "$1<i>$2</i>");
    // A heading marker keeps its emphasis rather than just losing its hash.
    t = t.replace(/(^|\n)[ \t]{0,3}#{1,6}[ \t]+([^\n]+)/g, "$1<b>$2</b>");
    // Whatever asterisks and backticks are left never closed. Out.
    t = t.replace(/\*+/g, "").replace(/`/g, "");
    return t;
  }).join("");
}

engine.markdownLite:
function markdownLite(text) {
  // Local, not a sibling top-level function: the bundler makes every
  // column-0 function its own chunk, and per evalBundle isolation a
  // sibling is not reliably callable from here.
  //
  // One line at a time. Escaping happens here, before any tag is
  // introduced, and the per-line scope is what stops a bullet's "*"
  // pairing with the next bullet's.
  function _mdlInline(line) {
    var s = String(line == null ? "" : line)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    s = s.replace(/`([^`]{1,200})`/g, "<code>$1</code>");
    s = s.replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
    s = s.replace(/(^|[^*])\*([^*\n]+)\*(?=[^*]|$)/g, "$1<i>$2</i>");
    return s;
  }
  var t = String(text == null ? "" : text).replace(/\r\n/g, "\n").trim();
  if (!t) return "";
  return t.split(/\n{2,}/).map(function (block) {
    var lines = block.split("\n").filter(function (l) { return l.trim(); });
    if (!lines.length) return "";
    var heading = lines.length === 1 && lines[0].match(/^\s*(#{1,4})\s+(.+)$/);
    if (heading) return "<b>" + _mdlInline(heading[2]) + "</b>";
    if (lines.every(function (l) { return /^\s*>\s?/.test(l); })) {
      return "<blockquote>" +
        lines.map(function (l) { return _mdlInline(l.replace(/^\s*>\s?/, "")); }).join("<br>") +
        "</blockquote>";
    }
    if (lines.every(function (l) { return /^\s*[-*•]\s+/.test(l); })) {
      return "<ul>" + lines.map(function (l) {
        return "<li>" + _mdlInline(l.replace(/^\s*[-*•]\s+/, "")) + "</li>";
      }).join("") + "</ul>";
    }
    if (lines.every(function (l) { return /^\s*\d+[.)]\s+/.test(l); })) {
      return "<ol>" + lines.map(function (l) {
        return "<li>" + _mdlInline(l.replace(/^\s*\d+[.)]\s+/, "")) + "</li>";
      }).join("") + "</ol>";
    }
    // A mixed block: render each line by its own kind, so a heading glued
    // to the paragraph under it still comes out as a heading.
    return "<p>" + lines.map(function (l) {
      var h = l.match(/^\s*(#{1,4})\s+(.+)$/);
      return h ? "<b>" + _mdlInline(h[2]) + "</b>" : _mdlInline(l);
    }).join("<br>") + "</p>";
  }).join("");
}

// One line at a time. Escaping happens here, before any tag is introduced,
// and the per-line scope is what stops a bullet's "*" pairing with the next
// bullet's.
// ─── Engine entry ────────────────────────────────────────────────────

// Build the prompt, call AI, parse the response, return both the parsed
// shape (action/answer/citations/followups) and the new history. Per
// evalBundle isolation, sibling helpers come in via providers.

engine.buildWorkingLines:
function buildWorkingLines(facts) {
  // [STEPS] The lines that rotate while Gemini answers. Each states
  // something really sent, or really asked of the model, for THIS question
  // (its inputs and the prompt's own rules), so every line is true for the
  // whole wait; the order (reading → checking → writing) is presentation —
  // the model doesn't report which part it is on. After one pass the
  // checking/writing lines loop, so it never looks like starting over.
  // facts: { words, paragraphs, sections, selection, trackedChanges,
  //   comments, highlights, history, attachment, docType, positions,
  //   locked, fallbacks, rules, followups, length, modify }
  var f = facts || {};
  function n(x) { return Number(x) || 0; }
  function many(k, one) { return n(k).toLocaleString() + " " + one + (n(k) === 1 ? "" : "s"); }
  var read = [], check = [], write = [];
  if (f.attachment) read.push("Reading the attached file");
  if (n(f.words)) read.push("Reading all " + many(f.words, "word"));
  if (f.selection) read.push("Focusing on your selection");
  if (n(f.trackedChanges)) { read.push("Reading " + many(f.trackedChanges, "tracked change")); read.push("Telling insertions from deletions"); }
  if (n(f.comments)) read.push("Reading " + many(f.comments, "comment"));
  if (f.highlights) read.push("Noting the highlighted text");
  if (f.history) read.push("Keeping earlier questions in mind");
  if (f.docType) read.push("It's " + (/^[AEIOU]/i.test(f.docType) ? "an " : "a ") + f.docType);
  if (n(f.paragraphs)) read.push("Going through " + many(f.paragraphs, "paragraph"));
  if (f.sections) check.push("Following the section structure");
  if (f.selection) check.push("Checking terms that affect it");
  if (f.sections || f.selection) check.push("Looking up the defined terms");
  if (f.sections) check.push("Checking how sections interact");
  if (n(f.positions)) check.push("Weighing " + many(f.positions, "Colgate position"));
  if (n(f.locked)) check.push("Checking " + many(f.locked, "locked clause"));
  if (n(f.fallbacks)) check.push("Comparing " + many(f.fallbacks, "fallback"));
  if (n(f.rules)) check.push("Checking " + many(f.rules, "team guidance rule"));
  check.push(f.attachment && !n(f.words) ? "Finding the parts it needs" : "Finding the clauses it needs");
  if (f.sections) check.push("Noting where each one sits");
  if (f.sections) write.push("Picking exact wording to cite");
  if (f.length === "short") write.push("Keeping it short, as you asked");
  if (f.length === "detailed") write.push("Covering every exception");
  if (f.modify) {
    // Rewrite / Draft on: the model may return replacement wording.
    write.push("Drafting the new wording");
    write.push("Keeping the section headings");
  } else {
    write.push("Writing the answer");
    write.push("Deciding whether to offer edits");
  }
  if (f.followups) write.push("Suggesting two next steps");
  return { first: read.concat(check, write), loop: check.concat(write) };
}

engine.analyze:
function analyze(input, providers) {
  var ai = providers && providers.ai;
  if (!ai || typeof ai.complete !== "function") {
    return Promise.reject(new Error("ask_eli: providers.ai.complete missing"));
  }
  var buildPrompt = providers && providers.buildPrompt;
  var capHist     = providers && providers.capHistory;
  var parseAi     = providers && providers.parseAiResponse;
  if (typeof buildPrompt !== "function" || typeof capHist !== "function" || typeof parseAi !== "function") {
    return Promise.reject(new Error("ask_eli: providers.buildPrompt + capHistory + parseAiResponse required"));
  }

  var prompt = buildPrompt(input);
  var aiOpts = {};
  if (input.signal) aiOpts.signal = input.signal;
  // PDF inline data (Gemini multimodal). Passed through unmodified.
  if (input.inlineData) {
    aiOpts.inlineData = input.inlineData;
  }
  aiOpts.sanitize = false;

  // Thoughts while it works, ONLY if both sides can do it: the view passed
  // an onThought, and the kernel has completeWithThoughts. An older kernel
  // has no such function, so this is ai.complete() exactly as before — and
  // on a new kernel with ai_show_thoughts off, completeWithThoughts IS
  // complete(). Either way the answer arrives the same way.
  var call = (typeof input.onThought === "function" && typeof ai.completeWithThoughts === "function")
    ? ai.completeWithThoughts(prompt, input.onThought, aiOpts)
    : ai.complete(prompt, aiOpts);

  return Promise.resolve(call).then(function (rawAnswer) {
    var parsed = parseAi(rawAnswer);
    // Normalize shape — guard against missing fields.
    var answer = parsed.answer || (parsed.action ? "" : String(rawAnswer));
    var newHistoryEntry = parsed.action === "replace_text"
      ? "Action Card: Document Modification Proposed."
      : answer;
    var newHistory = capHist((input.history || []).concat([
      { role: "user", content: input.question },
      { role: "model", content: newHistoryEntry },
    ]));
    return {
      raw: rawAnswer,
      action: parsed.action || null,
      target_original: parsed.target_original || "",
      proposed_new: parsed.proposed_new || "",
      explanation: parsed.explanation || "",
      answer: answer,
      citations: Array.isArray(parsed.citations) ? parsed.citations : [],
      followups: Array.isArray(parsed.followups) ? parsed.followups.slice(0, 2) : [],
      // The button that turns the advice into edits. A string when the
      // answer proposed a change to the open document, otherwise null —
      // and capped, because it is a label, not an instruction.
      applyAction: (typeof parsed.applyAction === "string" && parsed.applyAction.trim())
        ? parsed.applyAction.trim().slice(0, 40) : null,
      // [CONFIDENCE-STRIPES] pass-through — init's _finalizeResult reads
      // this when the stripes flag is on; harmless null otherwise.
      grounding: parsed.grounding || null,
      history: newHistory,
      overview: String(answer || "").replace(/<[^>]+>/g, "").substring(0, 200),
      provenance: {
        kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
        toolVersion: "v3.1",
        promptVersion: input.modifyMode ? "ask_eli_modify_v1" : "ask_eli_qa_v1",
        model: (ai.currentModel && ai.currentModel()) || null,
        docHash: input.docHash || null,
        timestamp: Date.now(),
      },
    };
  });
}

view.renderChat:
function renderChat(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initialHistory = opts.history || [];
  var welcomeName = opts.welcomeName || "there";
  var docTypeLabel = opts.docTypeLabel || "document";
  var initialSelection = opts.selectionText || "";
  var initialAttachment = opts.attachment || null; // { name, kind: "pdf"|"file"|"template" }
  var initialScope = opts.scope || "attached"; // "attached" | "both"
  var onSend = opts.onSend || function () {};
  var onBack = opts.onBack || function () {};
  var onClearHistory = opts.onClearHistory || function () {};
  var onAttachOpen = opts.onAttachOpen || function () {};
  var onAttachClear = opts.onAttachClear || function () {};
  var onScopeChange = opts.onScopeChange || function () {};
  var onModifyModeChange = opts.onModifyModeChange || function () {};
  var onImprove = opts.onImprove || null; // optional rewrite-prompt helper
  var onCitationClick = opts.onCitationClick || function () {};
  var onApplyAction = opts.onApplyAction || function () {};
  var onRejectAction = opts.onRejectAction || function () {};
  var onFollowup = opts.onFollowup || null;
  // Clicking "Make these changes" hands the answer to Revise Document.
  var onApplyAction = opts.onApplyAction || null;
  var onInsertAnswer = opts.onInsertAnswer || null; // edit-mode: drop answer text into the doc
  var onAddComments = opts.onAddComments || null;   // [COMMENTS] the answer's issues as Word comments
  var onRespond = opts.onRespond || null;           // [RESPOND] Respond to Redlines for the highlighted text

  // Edit-mode state. editMode drives contenteditable answers, the
  // selection→regen chip, and the Copy/Insert action row. _answerRegenHide
  // is wired by _initAnswerRegen() once the scroll area exists.
  var editMode = false;
  var _answerRegenHide = null;
  // markdownLite — passed in from init via opts. Falls back to plain
  // escape-with-br when not wired so the view never crashes if the
  // engine helper is missing.
  var markdownLite = opts.markdownLite || function (text) {
    return String(text == null ? "" : text)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/\n/g, "<br>");
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Compose the root. Layout (top → bottom):
  //   • header bar (back / title / clear)
  //   • scrolling bubble area (chat history)
  //   • scope segmented control (Live / Attached / Both — visible only
  //     when an attachment is present)
  //   • inputbox: textarea with a send button positioned inside its
  //     bottom-right; a small toolbar (Attach / Draft on the left, Improve
  //     beside Send once there is text) along the bottom. The duplicate "Whole document /
  //     Selection · N words" hint that previously sat below the input has
  //     been removed — selection awareness is surfaced inline above the
  //     textarea (selChip) instead.
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root _eli3_chat_root";
  root.innerHTML =
    // [HEADER-A] The gold line (3px, always); the drawer over the chat holds the bar (dropped by the ▾ tab) and the tab.
    '<div class="_eli3_ae_top">' +
    '<div class="_eli3_ae_drawer">' +
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back" title="Back">←</button>' +
      '<div class="_eli3_ae_title">Ask ELI' +
        '<span class="_eli3_ae_idxdot _eli3_ae_idxdot_busy" id="_eli3_ae_idxdot" title="Indexing the document…"></span>' +
        // [SETTINGS] Ask ELI settings (sliders, not ELI's main gear). Took
        // the place of eli_agent's Auto switch + mode caret, now in the dialog.
        '<button type="button" class="_eli3_ae_settings" id="_eli3_ae_settings" title="Ask ELI settings" aria-label="Ask ELI settings">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true">' +
            '<line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/>' +
            '<circle class="_eli3_ae_settings_knob" cx="8" cy="6" r="2.4"/><circle class="_eli3_ae_settings_knob" cx="16" cy="12" r="2.4"/><circle class="_eli3_ae_settings_knob" cx="10" cy="18" r="2.4"/>' +
          '</svg>' +
        '</button>' +
      '</div>' +
      '<button class="_eli3_chat_edittoggle" id="_eli3_chat_edittoggle" title="Edit mode — edit the answer inline, regenerate selections, copy or insert">Edit</button>' +
      '<button class="_eli3_chat_clear" title="Clear conversation">Clear</button>' +
    '</div>' +
    '<button type="button" class="_eli3_ae_pull" aria-label="Show Ask ELI\'s bar" aria-expanded="false">▾</button>' +
    '</div>' +
    '</div>' +
    '<div class="_eli3_chat_scroll" id="_eli3_chat_scroll"></div>' +
    '<div class="_eli3_chat_selchip" id="_eli3_chat_selchip" hidden></div>' +
    '<div class="_eli3_chat_scopebar" id="_eli3_chat_scopebar" hidden>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="live">📄 Live doc</button>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="attached">📎 Attachment</button>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="both">↔ Both</button>' +
    '</div>' +
    '<div class="_eli3_chat_inputbox">' +
      '<textarea class="_eli3_chat_input" id="_eli3_chat_input" rows="2" placeholder="Ask ELI about this document…"></textarea>' +
      '<button type="button" class="_eli3_chat_send" id="_eli3_chat_send" title="Send (Enter)">➤</button>' +
      '<div class="_eli3_chat_toolbar">' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_attach" id="_eli3_chat_attach" title="Attach file or template"></button>' +
        '<label class="_eli3_chat_tool _eli3_chat_drafttoggle" id="_eli3_chat_drafttoggle" title="Draft a new clause">' +
          '<input type="checkbox" id="_eli3_chat_draftchk">' +
          '<span>Draft</span>' +
        '</label>' +
        // [SELACTS-CENTER] Polish then Respond, as on the main screen: centred between Attach/Draft and Improve/Send.
        '<div class="_eli3_chat_selacts" id="_eli3_chat_selacts">' +
          '<button type="button" class="_eli3_chat_selact _eli3_chat_selact_polish" id="_eli3_chat_polish" hidden ' +
            'title="Open the Polish workspace — three rewrites to compare"><span class="_eli3_chat_selact_ico" aria-hidden="true">✎</span>Polish</button>' +
          '<button type="button" class="_eli3_chat_selact _eli3_chat_selact_respond" id="_eli3_chat_respond" hidden ' +
            'title="Answer the other side\'s changes in this text — accept, counter or reject each"><span class="_eli3_chat_selact_ico" aria-hidden="true">✨</span>Respond</button>' +
        '</div>' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_improve" id="_eli3_chat_improve" title="Improve your question">✨ <span class="_eli3_chat_tool_lbl">Improve</span></button>' +
      '</div>' +
    '</div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("._eli3_chat_clear").onclick = onClearHistory;
  root.querySelector("#_eli3_ae_settings").onclick = function () {
    if (typeof opts.onOpenSettings === "function") opts.onOpenSettings();
  };
  // Edit mode (replaces the old locate-pin toggle). When ON: hides the 📍
  // locate chips (so copy/insert grab clean text), makes every AI answer
  // body contenteditable, enables selection→regen, and swaps each answer's
  // follow-up suggestions for Copy + Insert buttons. Transient — exits on
  // the next question (see _doSend) or a manual re-click.
  var editBtn = root.querySelector("#_eli3_chat_edittoggle");
  // [SETTINGS] Citation pins hide in edit mode OR when the setting is off.
  var showPins = opts.showPins !== false;
  function _applyPins() { root.classList.toggle("_eli3_chat_hide_pins", editMode || !showPins); }
  _applyPins();
  // [ANSWER-STYLES] "Formatted answers": every rule in style.css's
  // [ANSWER-STYLES] block hangs off this class, so off draws answers as before.
  var formatted = opts.formatted === true;
  function _applyFormatted() { root.classList.toggle("_eli3_chat_fmt", formatted); }
  _applyFormatted();
  function _applyEditMode(on) {
    editMode = !!on;
    root.classList.toggle("_eli3_chat_edit_mode", editMode);
    _applyPins();
    if (editBtn) {
