      b.contentEditable = editMode ? "true" : "false";
    });
    if (!editMode && _answerRegenHide) _answerRegenHide();
  }
  if (editBtn) editBtn.onclick = function () { _applyEditMode(!editMode); };

  var scrollEl   = root.querySelector("#_eli3_chat_scroll");
  var selChipEl  = root.querySelector("#_eli3_chat_selchip");
  var scopeBarEl = root.querySelector("#_eli3_chat_scopebar");
  var inputEl    = root.querySelector("#_eli3_chat_input");
  var sendBtn    = root.querySelector("#_eli3_chat_send");
  var attachBtn  = root.querySelector("#_eli3_chat_attach");
  var improveBtn = root.querySelector("#_eli3_chat_improve");
  var draftChk   = root.querySelector("#_eli3_chat_draftchk");
  var boxEl      = root.querySelector("._eli3_chat_inputbox");
  var selActsEl  = root.querySelector("#_eli3_chat_selacts");
  var polishActBtn  = root.querySelector("#_eli3_chat_polish");
  var respondActBtn = root.querySelector("#_eli3_chat_respond");
  if (polishActBtn) polishActBtn.onclick = function (ev) {
    if (ev) { ev.preventDefault(); ev.stopPropagation(); }
    // Cross-tool dispatch — polish is tier:"preload", so its handler is registered before any tile click (receiver-tier
