  // Build the inline style="..." attribute (with trailing space) for a
  // formatted word. For del spans, combine line-through with underline so
  // strikethrough survives — inline text-decoration otherwise overrides
  // the .diff_del class's line-through.
  function _fmtStyleAttr(fmt, isDel) {
    if (!fmt) return "";
    var parts = [];
    if (fmt.bold)   parts.push("font-weight:bold");
    if (fmt.italic) parts.push("font-style:italic");
    if (fmt.underline) {
      parts.push(isDel ? "text-decoration:line-through underline" : "text-decoration:underline");
    }
    if (!parts.length) return "";
    return ' style="' + parts.join(";") + '"';
  }

  function _renderDiff(oldText, newText, originalFormatting) {
    var ot = String(oldText || ""), nt = String(newText || "");
    if (!ot.trim() && !nt.trim()) return '<i class="_eli3_chat_diff_empty">(no preview)</i>';
    if (typeof Diff === "undefined" || typeof Diff.diffArrays !== "function") {
      // Fallback when jsdiff didn't load — show side-by-side strikethrough.
      // The data attributes are inert (consumed only by the redline-regen
      // chip; ignored if regen is disabled or unmounted).
      return '<span class="_eli3_chat_diff_del" data-rl-t="del" data-rl-i="0">' + _esc(ot) + '</span> ' +
             '<span class="_eli3_chat_diff_add" data-rl-t="add" data-rl-i="0">' + _esc(nt) + '</span>';
    }
    // Tokenize words AND paragraph breaks (\n runs) so multi-paragraph
    // rewrites preview as multiple paragraphs. Newline tokens render as <br>
    // and are NOT counted as words — keeps formatting + regen word indices
    // identical to the single-paragraph behavior.
    var oldTokens = ot.replace(/\r\n?/g, "\n").match(/\S+|\n+/g) || [];
    var newTokens = nt.replace(/\r\n?/g, "\n").match(/\S+|\n+/g) || [];
