    // redline-regen chip (REDLINE REGEN section below) can map a user's
    // selection back to a hunk. Equal spans get tagged too so we can
    // identify "in-between context" inside a selection. data-rl-w is the
    // word's global index in the proposed text (used for splice).
    // oldWordIdx tracks position in oldTokens for formatting lookup (Show
    // clause only — null array → no-op, renders as before).
    var partIdx = 0;
    var newWordIdx = 0;
    var oldWordIdx = 0;
    parts.forEach(function (p) {
      if (!p.added && !p.removed) {
        p.value.forEach(function (w) {
          if (/^\n+$/.test(w)) { html += _brFor(w); return; }   // paragraph break — no word index
          var fmt = originalFormatting && originalFormatting[oldWordIdx];
          var styleAttr = _fmtStyleAttr(fmt, false);
          html += '<span' + styleAttr + ' data-rl-t="eq" data-rl-i="' + partIdx + '" data-rl-w="' + newWordIdx + '">' + _esc(w) + '</span> ';
          oldWordIdx++;
          newWordIdx++;
        });
      } else if (p.removed) {
        // Deletion → not in newTokens, so no word index. Still tagged so the
        // chip can detect "user selected only deleted text" and offer "Keep".
        p.value.forEach(function (w) {
          if (/^\n+$/.test(w)) { return; }   // removed paragraph break — collapse, no render/index
          var fmt = originalFormatting && originalFormatting[oldWordIdx];
          var styleAttr = _fmtStyleAttr(fmt, true);
          html += '<span class="_eli3_chat_diff_del"' + styleAttr + ' data-rl-t="del" data-rl-i="' + partIdx + '">' + _esc(w) + '</span> ';
          oldWordIdx++;
        });
      } else {
        // AI-authored insertion. No formatting — plain green is honest
        // signal that the AI added these words.
        p.value.forEach(function (w) {
          if (/^\n+$/.test(w)) { html += _brFor(w); return; }   // added paragraph break
          html += '<span class="_eli3_chat_diff_add" data-rl-t="add" data-rl-i="' + partIdx + '" data-rl-w="' + newWordIdx + '">' + _esc(w) + '</span> ';
          newWordIdx++;
        });
      }
      partIdx++;
    });
    return html.trim();
  }

  // ────────────────────────────────────────────────────────────────
  // ── REDLINE REGEN ──────────────────────────────────────────────
  // Adds a floating chip when the user selects text inside the action
  // card's redline preview. The chip offers preset rewrite directives
  // (different, stronger, shorter, cautious, plain) plus "Keep original"
  // for deletion-only selections. The selected span is mapped back to a
  // range in the proposed text via the data-rl-w word indices that
  // `_renderDiff` plants on add/eq spans. The AI returns a replacement
  // string; we splice it into proposed text, update the closure variable
  // + payload.proposed_new, and repaint the diff.
  //
  // GATED BY SETTING: ask_eli_redline_regen_enabled — kill-switch admin
