    { key: "different", icon: "🔄", label: "Different", directive: "Generate a different version of the bracketed words that conveys roughly the same meaning but uses different phrasing." },
    { key: "stronger",  icon: "💪", label: "Stronger",  directive: "Generate a version of the bracketed words more favorable to us (Colgate) — narrower obligations on Colgate, broader rights and protections for Colgate, tighter carve-outs against Colgate, longer cure periods for Colgate, stricter constraints on the counterparty." },
    { key: "shorter",   icon: "✂",  label: "Shorter",   directive: "Generate a more concise version of the bracketed words that preserves the substantive meaning." },
    { key: "lengthen",  icon: "📝", label: "Lengthen",  directive: "Expand the bracketed words with additional precision and supporting language — cover edge cases that the original glosses over." },
  ];
  // Returns false if the regen kill switch is off, so addActionCard can
  // skip attaching the chip entirely. Defaults to enabled if the setting
  // hasn't been registered yet (race-safe with init.js boot).
  function _redlineRegenEnabled() {
    try {
      var s = window.eli && window.eli.settings;
      if (!s || typeof s.get !== "function") return true;
      var v = s.get("ask_eli_redline_regen_enabled");
