// ─── [SETTINGS] Ask ELI settings dialog body ─────────────────────────
// Pure render. opts.sections: [{ title, rows }]; a row is
//   { type: "info", label, value, help }
//   { type: "switch" | "select" | "segmented", key, label, help, value,
//     options: [{ value, label }], locked, onChange(value) }
//   { type: "action", label, run(linkEl) }
// locked = pushed by an admin: shown, not changeable.
// opts.tabs: [{ title, sections }] instead — a tab strip, the first tab shown.

view.renderAskSettings:
function renderAskSettings(opts) {
  var esc = function (s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };
  if (opts.tabs && opts.tabs.length) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_aeset";
    var strip = document.createElement("div");
    strip.className = "_eli3_aeset_tabs";
    strip.setAttribute("role", "tablist");
    wrap.appendChild(strip);
    var panes = opts.tabs.map(function (tab, i) {
      var b = document.createElement("button");
      b.type = "button";
      b.textContent = tab.title || "";
      b.setAttribute("role", "tab");
      b.setAttribute("data-aeset-tab", String(i));
      strip.appendChild(b);
      var pane = renderAskSettings({ sections: tab.sections });
      pane.setAttribute("role", "tabpanel");
      wrap.appendChild(pane);
      return { b: b, pane: pane };
    });
    var show = function (k) {
      panes.forEach(function (x, i) {
        x.b.className = "_eli3_aeset_tab" + (i === k ? " _eli3_aeset_tab_on" : "");
        x.b.setAttribute("aria-selected", i === k ? "true" : "false");
        x.pane.style.display = i === k ? "" : "none";
      });
    };
    panes.forEach(function (x, i) { x.b.onclick = function () { show(i); }; });
    show(0);
    return wrap;
  }
  var root = document.createElement("div");
  root.className = "_eli3_aeset";
  (opts.sections || []).forEach(function (sec) {
    if (!sec || !sec.rows || !sec.rows.length) return;
    var h = document.createElement("div");
    h.className = "_eli3_aeset_sec";
    h.textContent = sec.title || "";
    root.appendChild(h);
    sec.rows.forEach(function (r) {
      var row = document.createElement("div");
      row.className = "_eli3_aeset_row" + (r.type === "action" ? " _eli3_aeset_row_action" : "");
      if (r.key) row.setAttribute("data-aeset-key", r.key);
      if (r.type === "action") {
        var a = document.createElement("button");
        a.type = "button";
        a.className = "_eli3_aeset_link";
        a.textContent = r.label;
        a.onclick = function () { if (typeof r.run === "function") r.run(a); };   // (the link itself: a row that says what it did)
        row.appendChild(a);
        root.appendChild(row);
        return;
      }
      var txt = document.createElement("div");
      txt.className = "_eli3_aeset_txt";
      txt.innerHTML = '<div class="_eli3_aeset_name">' + esc(r.label) + '</div>' +
        (r.help ? '<div class="_eli3_aeset_help">' + esc(r.help) + '</div>' : '') +
        (r.locked ? '<div class="_eli3_aeset_lock">Set by your admin</div>' : '');
      row.appendChild(txt);
      var ctl;
      if (r.type === "info") {
        ctl = document.createElement("div");
        ctl.className = "_eli3_aeset_value";
        ctl.textContent = r.value || "";
      } else if (r.type === "switch") {
        ctl = document.createElement("button");
        ctl.type = "button";
        ctl.setAttribute("role", "switch");
        var on = !!r.value;
        var paint = function () {
          ctl.className = "_eli3_aeset_sw" + (on ? " _eli3_aeset_sw_on" : "");
          ctl.setAttribute("aria-checked", on ? "true" : "false");
          ctl.setAttribute("aria-label", r.label);
        };
        paint();
        ctl.disabled = !!r.locked;
        ctl.onclick = function () { on = !on; paint(); if (typeof r.onChange === "function") r.onChange(on); };
      } else if (r.type === "segmented") {
        ctl = document.createElement("div");
        ctl.className = "_eli3_aeset_seg";
        ctl.setAttribute("role", "radiogroup");
        ctl.setAttribute("aria-label", r.label);
        (r.options || []).forEach(function (o) {
          var b = document.createElement("button");
          b.type = "button";
          b.textContent = o.label;
          b.setAttribute("role", "radio");
          b.setAttribute("data-value", o.value);
          b.disabled = !!r.locked;
          ctl.appendChild(b);
        });
        var paintSeg = function (v) {
          Array.prototype.forEach.call(ctl.children, function (b) {
            var sel = b.getAttribute("data-value") === v;
            b.className = sel ? "_eli3_aeset_seg_on" : "";
            b.setAttribute("aria-checked", sel ? "true" : "false");
          });
        };
        paintSeg(r.value);
        ctl.onclick = function (ev) {
          var b = ev.target && ev.target.closest && ev.target.closest("button");
          if (!b || b.disabled) return;
          var v = b.getAttribute("data-value");
          paintSeg(v);
          if (typeof r.onChange === "function") r.onChange(v);
        };
      } else if (r.type === "select") {
        ctl = document.createElement("select");
        ctl.className = "_eli3_aeset_sel";
        ctl.setAttribute("aria-label", r.label);
        (r.options || []).forEach(function (o) {
          var op = document.createElement("option");
          op.value = o.value;
          op.textContent = o.label;
          if (o.value === r.value) op.selected = true;
          ctl.appendChild(op);
        });
        ctl.disabled = !!r.locked;
        ctl.onchange = function () { if (typeof r.onChange === "function") r.onChange(ctl.value); };
      }
      if (ctl) row.appendChild(ctl);
      root.appendChild(row);
    });
  });
  return root;
}

// ─── [COMMENTS] Add as comments: the dialog body ─────────────────────
// Pure render of one step. init owns the state and redraws on every change
// except typing, so a comment being edited keeps its caret. state:
