view.renderCommentsPanel:
function renderCommentsPanel(state, on) {
  var s = state || {}, h = on || {};
  var esc = function (t) {
    return String(t == null ? "" : t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
