  var root = document.createElement("div");
  root.className = "_eli3_cm";
  function el(tag, cls, html) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html != null) e.innerHTML = html;
    return e;
  }
  function btn(label, cls, fn, disabled) {
    var b = el("button", "_eli3_cm_btn" + (cls ? " " + cls : ""));
    b.type = "button";
    b.textContent = label;
    if (disabled) b.disabled = true;
    b.onclick = function () { if (!b.disabled && typeof fn === "function") fn(); };
    return b;
  }
  function seg(options, value, fn, cls) {
    var g = el("span", "_eli3_cm_seg" + (cls ? " " + cls : ""));
    options.forEach(function (o) {
      var b = el("button", o.value === value ? "_eli3_cm_seg_on" : "");
      b.type = "button";
      b.textContent = o.label;
      b.onclick = function () { if (o.value !== value && typeof fn === "function") fn(o.value); };
      g.appendChild(b);
    });
    return g;
  }
  function foot(note, primary) {
    var f = el("div", "_eli3_cm_foot");
    f.appendChild(el("span", "_eli3_cm_note", esc(note)));
    if (primary) f.appendChild(primary);
    return f;
  }
  var AUD = {
    team: { name: "My team", mark: "CP", desc: "Candid notes for colleagues. Can cite <b>Colgate positions, the playbook and fallbacks</b>. Each starts “Internal:” so it is never sent by mistake." },
    other: { name: "The other side", mark: "OS", desc: "Professional and specific: what should change and why — fair, market practice, or <b>Colgate policy</b> (“Colgate policy requires net 90”). <b>Never mentions the playbook, fallbacks or Colgate's internal positions.</b>" },
  };
  var PRI = { must: "Must", worth: "Worth raising", minor: "Minor" };

  if (s.step === "who") {
    root.appendChild(el("div", "_eli3_cm_q", "Who will read these comments?"));
    root.appendChild(el("div", "_eli3_cm_qsub", "ELI writes them differently for each."));
    ["team", "other"].forEach(function (a) {
      var c = el("button", "_eli3_cm_who" + (s.audience === a ? " _eli3_cm_who_on" : ""),
        '<span class="_eli3_cm_who_t"><span class="_eli3_cm_mark _eli3_cm_mark_' + a + '">' + AUD[a].mark + "</span>" + AUD[a].name + "</span>" +
        '<span class="_eli3_cm_who_d">' + AUD[a].desc + "</span>");
      c.type = "button";
      c.onclick = function () { if (typeof h.pick === "function") h.pick(a); };
      root.appendChild(c);
    });
    if (s.audience === "other") {
      root.appendChild(el("div", "_eli3_cm_shield", "For the other side, ELI checks each comment for wording that gives away Colgate's thinking, and leaves any such comment unticked for you to fix."));
    }
    var rem = el("label", "_eli3_cm_remember");
    var cb = el("input");
    cb.type = "checkbox";
    cb.checked = !!s.remember;
    cb.onchange = function () { if (typeof h.remember === "function") h.remember(cb.checked); };
    rem.appendChild(cb);
    rem.appendChild(document.createTextNode(" Don't ask again while this document is open"));
    root.appendChild(rem);
    root.appendChild(foot("Nothing is added until you review.", btn("Write the comments", "_eli3_cm_gold", h.start, !s.audience)));
    return root;
  }

  if (s.step === "working" || s.step === "adding") {
    var w = el("div", "_eli3_cm_working", '<span class="_eli3_cm_spin"></span><span>' + esc(s.note || "Working…") + "</span>");
    root.appendChild(w);
    return root;
  }

  if (s.step === "error") {
    root.appendChild(el("div", "_eli3_cm_err", esc(s.note || "Something went wrong.")));
    root.appendChild(foot("", btn("Close", "", h.close)));
    return root;
  }

  var list = Array.isArray(s.comments) ? s.comments : [];

  if (s.step === "done") {
    var placed = list.filter(function (c) { return c.placed; }).length;
    root.appendChild(el("div", "_eli3_cm_big", placed === 1 ? "1 comment added" : placed + " comments added"));
    list.forEach(function (c, i) {
      if (!c.keep && !c.placed && !c.error) return;
      var r = el("div", "_eli3_cm_row");
      r.appendChild(el("span", "_eli3_cm_row_t",
        (c.placed ? '<span class="_eli3_cm_ok">✓</span> ' : '<span class="_eli3_cm_miss">!</span> ') + esc(c.issue) +
        (c.placed && c.wholeClause ? ' <span class="_eli3_cm_sub">on the whole clause</span>' : "") +
        (c.placed && c.reply ? ' <span class="_eli3_cm_sub">reply to ' + esc(c.replyToAuthor || "their comment") + "</span>" : "") +
        (!c.placed ? ' <span class="_eli3_cm_sub">' + esc(c.error || "Couldn't place it.") + "</span>" : "")));
      if (c.placed) {
        var lk = btn("Locate", "_eli3_cm_link", function () { if (typeof h.locate === "function") h.locate(i); });
        r.appendChild(lk);
      }
      root.appendChild(r);
    });
    var f = el("div", "_eli3_cm_foot");
    f.appendChild(placed ? btn("Remove these comments", "", h.remove) : el("span", "_eli3_cm_note", ""));
    f.appendChild(btn("Done", "_eli3_cm_gold", h.close));
    root.appendChild(f);
    return root;
  }

  // review
  var bar = el("div", "_eli3_cm_bar");
  bar.appendChild(seg([{ value: "team", label: "My team" }, { value: "other", label: "The other side" }], s.audience, h.switchAudience));
  var picks = el("span", "_eli3_cm_picks");
  [["all", "All"], ["must", "Must-haves"], ["none", "None"]].forEach(function (p) {
    picks.appendChild(btn(p[1], "_eli3_cm_link", function () { if (typeof h.quick === "function") h.quick(p[0]); }));
  });
  bar.appendChild(picks);
  root.appendChild(bar);
  if (!list.length) root.appendChild(el("div", "_eli3_cm_empty", "ELI found nothing to comment on."));
  list.forEach(function (c, i) {
    var card = el("div", "_eli3_cm_card" + (c.keep ? "" : " _eli3_cm_card_off"));
    card.appendChild(el("div", "_eli3_cm_ch",
      '<span class="_eli3_cm_issue">' + esc(c.issue) + '</span><span class="_eli3_cm_pri _eli3_cm_pri_' + esc(c.priority) + '">' + esc(PRI[c.priority] || "") + "</span>"));
    card.appendChild(c.reply
      ? (c.noClause
        ? el("div", "_eli3_cm_anchor _eli3_cm_whole _eli3_cm_noclause", "That comment isn't in the document — this reply can't be added")
        : el("div", "_eli3_cm_re", '<span class="_eli3_cm_re_k">Reply to ' + esc(c.replyToAuthor || "their comment") + '</span>' +
            '<span class="_eli3_cm_re_t">“' + esc(c.replyToText) + '”</span>'))
      : c.noClause
      ? el("div", "_eli3_cm_anchor _eli3_cm_whole _eli3_cm_noclause", "No matching clause in the document — this one can't be placed")
      : c.anchor
        ? el("div", "_eli3_cm_anchor", "“" + esc(c.anchor) + "”")
        : el("div", "_eli3_cm_anchor _eli3_cm_whole", "On the whole clause"));
    var ta = el("textarea", "_eli3_cm_text");
    ta.value = c.text || "";
    ta.rows = 2;
    // The whole comment shows, whatever the dialog's width: the box fits its
    // text once it is on screen, and again as you type.
    var fit = function (box) { box.style.height = "auto"; box.style.height = (box.scrollHeight + 2) + "px"; };
    ta.oninput = function () { fit(ta); if (typeof h.edit === "function") h.edit(i, ta.value); };
    requestAnimationFrame(fit.bind(null, ta));
    card.appendChild(ta);
    // Where it came from — for you, never put in the comment.
    if (c.source) card.appendChild(el("div", "_eli3_cm_src", '<span class="_eli3_cm_src_k">Based on</span> ' + esc(c.source)));
    if (c.leak) {
      card.appendChild(el("div", "_eli3_cm_warn", "Mentions “" + esc(c.leak) + "”, which reads as Colgate's own thinking. Edit it before you tick it."));
    }
    if (c.policy) {
      card.appendChild(el("div", "_eli3_cm_warn", "Says “Colgate policy”, but no Colgate requirement on file backs it. Edit it before you tick it."));
    }
    var cf = el("div", "_eli3_cm_cf");
    if (c.noClause) {
      cf.appendChild(el("span", "_eli3_cm_note", "Not added"));
    } else {
      cf.appendChild(seg([{ value: true, label: "Keep" }, { value: false, label: "Skip" }], !!c.keep, function (v) {
        if (typeof h.toggle === "function") h.toggle(i, v);
      }, "_eli3_cm_seg_sm"));
      cf.appendChild(btn("Locate", "_eli3_cm_link", function () { if (typeof h.locate === "function") h.locate(i); }));
    }
    card.appendChild(cf);
    root.appendChild(card);
  });
  var n = list.filter(function (c) { return c.keep; }).length;
  root.appendChild(foot(n + " of " + list.length + " selected",
    btn(n === 1 ? "Add 1 comment" : "Add " + n + " comments", "_eli3_cm_gold", h.add, n === 0)));
  return root;
}

// ─── Attach modal ────────────────────────────────────────────────────
// FROM v2 buildSourceMenuDialog. Two-tab modal: Upload File / Saved
// Templates. Uses showEliDialog as the host. opts.templates is an array
// of {id, label, content, library, category} from the templates store.

view.renderAttachDialog:
function renderAttachDialog(opts) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  var templates = opts.templates || [];
  var onPickFile = opts.onPickFile || function () {};
  var onPickTemplate = opts.onPickTemplate || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Group templates by library / agreementType.
  var grouped = {};
  templates.forEach(function (t) {
    if (!t || !t.id || String(t.id).charAt(0) === "_") return;
    var lib = t.library || t.category || t.agreementType || "Library";
    if (!grouped[lib]) grouped[lib] = [];
    grouped[lib].push(t);
  });

  // 2026-05-13 follow-up: saved templates COLLAPSED by default to keep
  // the dialog short. Affordance comes from a styled "click-to-expand"
  // summary (chevron + label + count badge + hover state — see
  // style.css `._eli3_chat_attach_group summary`).
  var groupHtml = Object.keys(grouped).sort().map(function (lib) {
    var items = grouped[lib];
    return '<details class="_eli3_chat_attach_group">' +
      '<summary>' +
        '<span class="_eli3_chat_attach_chev" aria-hidden="true">▸</span>' +
        '<span class="_eli3_chat_attach_grouplbl">' + _esc(lib) + '</span>' +
        '<span class="_eli3_chat_attach_count">' + items.length + '</span>' +
        '<span class="_eli3_chat_attach_hint">Click to expand</span>' +
      '</summary>' +
      '<div class="_eli3_chat_attach_items">' +
        items.map(function (t) {
          var name = t.label || t.name || t.id;
          return '<button type="button" class="_eli3_chat_attach_item" data-tpl-id="' + _esc(t.id) + '" title="Click to attach this template">' +
            '<span class="_eli3_chat_attach_item_icon">📄</span>' +
            '<span class="_eli3_chat_attach_item_name">' + _esc(name) + '</span>' +
            '<span class="_eli3_chat_attach_item_action">Attach →</span>' +
          '</button>';
        }).join("") +
      '</div>' +
    '</details>';
  }).join("");

  var bodyHtml =
    '<div class="_eli3_chat_attach_body">' +
      '<div class="_eli3_chat_attach_section">' +
        '<div class="_eli3_chat_attach_secthead">📁 Upload File</div>' +
        '<label class="_eli3_chat_attach_drop" for="_eli3_chat_attach_file">' +
          '<div class="_eli3_chat_attach_drop_icon">📎</div>' +
          '<div class="_eli3_chat_attach_drop_title">Click to choose a file or drop one here</div>' +
          '<div class="_eli3_chat_attach_drop_sub">PDF stays inline · DOCX/TXT extract to text · up to 5 MB</div>' +
        '</label>' +
        '<input type="file" id="_eli3_chat_attach_file" ' +
          'accept=".pdf,application/pdf,' +
                  '.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,' +
                  '.txt,text/plain" ' +
          'hidden>' +
      '</div>' +
      (templates.length
        ? '<div class="_eli3_chat_attach_section">' +
            '<div class="_eli3_chat_attach_secthead">📚 Saved Templates</div>' +
            groupHtml +
          '</div>'
        : '<div class="_eli3_chat_attach_section _eli3_chat_attach_empty">No saved templates. Use Build Draft → Templates to add some.</div>') +
    '</div>';

  // ask_dock: when Ask ELI is open inside the dock's slide-down panel
  // (z-index 10001), the kernel's default eli-overlay (z-index 9999) sits
  // BEHIND the panel — modal appears unreachable. Bump above 10002 (the
  // dock handle) so the dialog always sits on top of the dock chrome.
  var _dockOpen = !!document.getElementById("_eli3_askdock_panel");
  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_chat_attach_dialog",
    icon: "📎",
    title: "Attach to chat",
    body: bodyHtml,
    zIndex: _dockOpen ? 10500 : undefined,
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      var fileInp = overlay.querySelector("#_eli3_chat_attach_file");
      if (fileInp) fileInp.onchange = function (e) {
        var f = e.target.files && e.target.files[0];
        if (!f) return;
        onPickFile(f);
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      };
      Array.prototype.forEach.call(overlay.querySelectorAll("[data-tpl-id]"), function (btn) {
        btn.onclick = function () {
          var id = btn.getAttribute("data-tpl-id");
          var t = templates.find(function (tt) { return String(tt.id) === id; });
          if (t) onPickTemplate(t);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderDropZoneJumper — FROM v2 showEliDropZoneJumper (line 11726).
// Top-of-pane overlay that asks the user to position their cursor in
// Word, then click "Insert clause" to drop the AI-drafted text at that
// cursor. Used by Draft mode when the AI returns a `replace_text`-style
// action card with NO target_original (pure draft, no clause to replace).

view.renderDropZoneJumper:
function renderDropZoneJumper(opts) {
  var htmlContent = opts.htmlContent || "";
  var mode = opts.mode || "draft";
  var noRedlines = !!opts.noRedlines;
  var onInsert = opts.onInsert || function () {};
  var onCancel = opts.onCancel || function () {};

  var overlay = document.createElement("div");
  overlay.className = "_eli3_chat_dropzone_overlay";
  var msg = (mode === "rewrite")
    ? "Select clause to replace, then click Insert clause."
    : "Place cursor where you want to insert the clause, then click Insert clause.";
  overlay.innerHTML =
    '<div class="_eli3_chat_dropzone_btnrow">' +
      '<button type="button" class="_eli3_chat_dropzone_cancel">Cancel</button>' +
      '<button type="button" class="_eli3_chat_dropzone_insert">⬇️ Insert clause</button>' +
    '</div>' +
    '<div class="_eli3_chat_dropzone_msg">' + msg + '</div>';
  document.body.appendChild(overlay);
  var cancelBtn = overlay.querySelector("._eli3_chat_dropzone_cancel");
  var insertBtn = overlay.querySelector("._eli3_chat_dropzone_insert");
  cancelBtn.onclick = function () {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    onCancel();
  };
  insertBtn.onclick = function () {
    insertBtn.disabled = true;
    insertBtn.textContent = "Dropping…";
    Promise.resolve(onInsert({ htmlContent: htmlContent, noRedlines: noRedlines })).then(function () {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }).catch(function () {
      insertBtn.disabled = false;
      insertBtn.textContent = "Error — try again";
    });
  };
  return {
    close: function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); },
  };
}

// ─── Document viewer ─────────────────────────────────────────────────
// Opens an overlay showing the attached document with the best formatting
// we can produce. Routes by attachment kind:
//   - PDF: browser-native viewer in an iframe, jumps to #page=N
//   - DOCX (with html): mammoth-converted HTML rendered in a scrollable
//     panel; cited paragraph is highlighted + scrolled into view
//   - TXT / DOCX (no html): plain text with paragraph breaks, cited
//     paragraph highlighted + scrolled into view
// citation { id: "ATT_5" | "ATT_P3" | "ATT_PDF", text: "..." }
// FROM v3 ask_eli — not in v2; new behavior 2026-05-16.

view.renderDocViewer:
function renderDocViewer(opts) {
  // SELF-CONTAINED: bundler wraps each view fn in `new Function(...)` so
  // sibling-fn refs (like _esc) don't resolve at call time. Inline
  // the helper here. Same rule as engine functions.
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  opts = opts || {};
  var attachment = opts.attachment || {};
  var citation = opts.citation || {};
  var onClose = opts.onClose || function () {};
  var name = attachment.name || "Attached document";
  var kind = attachment.kind;
  var citeId = String(citation.id || "");
  var citeText = String(citation.text || "");
  // Parse citation id → { paraIdx?: number, pageNum?: number }
  var paraMatch = citeId.match(/^ATT_(\d+)$/);
  var pageMatch = citeId.match(/^ATT_P(\d+)$/);
  var paraIdx = paraMatch ? parseInt(paraMatch[1], 10) : null;
  var pageNum = pageMatch ? parseInt(pageMatch[1], 10) : null;
  var overlay = document.createElement("div");
  overlay.className = "_eli3_doc_viewer_overlay";
  var bodyHtml = "";
  var pdfBytes = null;
  if (kind === "pdf" && attachment.data) {
    // pdf.js (window.pdfjsLib) must be loaded via Script Lab Libraries tab:
    //   https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js
    // Renders each page to a canvas — works in Office.js sandboxed
    // iframes where data:/blob: PDF URLs are refused.
    try {
      var bin = atob(attachment.data);
      pdfBytes = new Uint8Array(bin.length);
      for (var bi2 = 0; bi2 < bin.length; bi2++) pdfBytes[bi2] = bin.charCodeAt(bi2);
    } catch (e) { pdfBytes = null; }
    if (!pdfBytes) {
      bodyHtml = '<div class="_eli3_doc_viewer_empty">Could not decode PDF for preview.</div>';
    } else if (typeof window.pdfjsLib === "undefined") {
      bodyHtml = '<div class="_eli3_doc_viewer_empty">' +
        '<div style="font-weight:700;margin-bottom:8px;color:#1e293b;">PDF library not loaded</div>' +
        '<div style="font-size:12px;line-height:1.6;">Add this URL to Script Lab\'s <b>Libraries</b> tab and reload:</div>' +
        '<div style="margin-top:8px;padding:8px 10px;background:#1e293b;color:#cbd5e1;font-family:ui-monospace,monospace;font-size:11px;text-align:left;user-select:all;">' +
        'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js' +
        '</div></div>';
    } else {
      bodyHtml = '<div class="_eli3_doc_viewer_pdf_canvas_host">' +
                 '<div class="_eli3_doc_viewer_pdf_status" id="_eli3_pdfstatus">Reading PDF…</div>' +
                 '<div class="_eli3_doc_viewer_pdf_pages" id="_eli3_pdfpages"></div>' +
                 '</div>';
    }
  } else if (attachment.html) {
    // Mammoth-converted HTML. We wrap paragraphs with ids so we can
    // scroll/highlight by paraIdx. mammoth emits <p>, <h1-6>, <ul>, <ol>.
    // Each top-level block element gets data-att-para-idx; we walk the
    // DOM after insertion to assign these (cleaner than regex).
    bodyHtml = '<div class="_eli3_doc_viewer_html">' + attachment.html + '</div>';
  } else if (attachment.text) {
    // Plain text fallback. Render each paragraph as <p data-att-para-idx="N">.
    var paras = String(attachment.text).split(/\n\s*\n/).map(function (p) {
      return p.replace(/\s+/g, " ").trim();
    }).filter(function (p) { return p.length > 0; });
    if (paras.length === 0) paras = [String(attachment.text)];
    bodyHtml = '<div class="_eli3_doc_viewer_text">' +
      paras.map(function (p, i) {
        return '<p data-att-para-idx="' + (i + 1) + '">' + _esc(p) + '</p>';
      }).join("") +
      '</div>';
  } else {
    bodyHtml = '<div class="_eli3_doc_viewer_empty">No preview available for this attachment.</div>';
  }
  var citeBanner = citeText
    ? '<div class="_eli3_doc_viewer_cite">' +
        '<div class="_eli3_doc_viewer_cite_label">ELI cited from this document:</div>' +
        '<div class="_eli3_doc_viewer_cite_text">' + _esc(citeText.substring(0, 400)) + '</div>' +
      '</div>'
    : "";
  overlay.innerHTML =
    '<div class="_eli3_doc_viewer_card">' +
      '<div class="_eli3_doc_viewer_head">' +
        '<div class="_eli3_doc_viewer_title">📎 ' + _esc(name) + '</div>' +
        '<button class="_eli3_doc_viewer_close" type="button" aria-label="Close">✕</button>' +
      '</div>' +
      citeBanner +
      '<div class="_eli3_doc_viewer_body">' + bodyHtml + '</div>' +
    '</div>';
  document.body.appendChild(overlay);
  var closeBtn = overlay.querySelector("._eli3_doc_viewer_close");
  function close() {
    try { overlay.remove(); } catch (e) {}
    try { onClose(); } catch (e) {}
  }
  if (closeBtn) closeBtn.onclick = close;
  overlay.onclick = function (e) { if (e.target === overlay) close(); };
  // ESC to close
  function escHandler(e) {
    if (e.key === "Escape") { close(); document.removeEventListener("keydown", escHandler); }
  }
  document.addEventListener("keydown", escHandler);
  // For HTML/text bodies, assign para indices + highlight + scroll.
  if (kind !== "pdf") {
    var bodyRoot = overlay.querySelector("._eli3_doc_viewer_body");
    if (bodyRoot) {
      // For mammoth HTML we walk ALL top-level block elements and stamp
      // data-att-para-idx. Match must mirror what init.js _readFile uses
      // to extract paragraphs (doc.body.children, including any blocks
      // with non-empty textContent). For text fallback we already stamped
      // them above. 2026-05-16: filter to blocks with non-empty text —
      // pure-decoration nodes (empty paragraphs, page breaks) shouldn't
      // shift the index. Same filter as init.js.
      var htmlRoot = bodyRoot.querySelector("._eli3_doc_viewer_html");
      if (htmlRoot) {
        var nextIdx = 1;
        for (var bi = 0; bi < htmlRoot.children.length; bi++) {
          var el = htmlRoot.children[bi];
          var t = String(el.textContent || "").replace(/\s+/g, " ").trim();
          if (!t) continue;
          el.setAttribute("data-att-para-idx", String(nextIdx));
          nextIdx++;
        }
      }
      // 2026-05-16: prefer EXACT-TEXT highlight (just the cited words),
      // not block-level. Whole-block highlight bleeds visually when the
      // block is a table, list, or long paragraph. Strategy:
      //   1. Find the target block via paraIdx (preferred) or text search
      //   2. Inside that block, locate the cite text via TreeWalker +
      //      Range API and wrap it in <mark>
      //   3. Scroll the mark into view
      //   4. Block-level fallback only when exact text isn't found inside
      function _highlightTextIn(block, probe) {
        if (!block || !probe) return null;
        var lo = String(probe).toLowerCase().trim();
        if (!lo) return null;
        var bodyText = (block.textContent || "").toLowerCase();
        var startG = bodyText.indexOf(lo);
        // Probe miss → try first ~50 chars only (AI may have paraphrased the tail)
